export function createRateLimiter() {
    const WINDOW_MS = 1000;
    const MAX_REQUESTS = 3;

    /**
     * Internal state stores the timestamps of requests for each key.
     * Map<key, number[]> where number[] contains request timestamps (nowMs).
     */
    const keyTimestamps = new Map<string, number[]>();

    const allow = (key: string, nowMs: number): boolean => {
