        // 1. Clean up old requests outside the sliding window
        const windowStart = nowMs - WINDOW_MS;

        // Filter out timestamps older than the window start
        // Since we are only interested in the current count within the window,
        // we don't strictly need to mutate the map history unless we want perfect storage optimization.
        // However, for correctness and avoiding state bloat (if requests happen far apart), 
