export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;

  /**
   * Internal state storage for rate limiting.
   * Key: string (rate limiter key)
   * Value: { windowStart: number, count: number }
   */
  const state = new Map<string, { windowStart: number, count: number }>();

  const allow = (key: string, nowMs: number): boolean => {
    const entry = state.get(key);
    let windowStart;
    let count;

    if (!entry) {
      // New window initialization
      windowStart = nowMs;
      count = 0;
      state.set(key, { windowStart: windowStart, count: count });
      return true; // Allowed for the first request in a new window
    } else {
      windowStart = entry.windowStart;
      count = entry.count;

      // Boundary Reset Rule check
      if (nowMs - windowStart >= WINDOW_MS) {
        // Start a fresh window
        windowStart = nowMs;
        count = 0;
        state.set(key, { windowStart: windowStart, count: count });
      }

      // Check quota
      if (count < LIMIT) {
        // Success: Increment count and update state
        state.set(key, { windowStart: windowStart, count: count + 1 });
        return true;
      } else {
        // Rejected
        return false;
      }
    }
  };

  const remaining = (key: string, nowMs: number): number => {
    const entry = state.get(key);
    if (!entry) {
      // If the key has never been requested, assume full capacity for demonstration purposes 
      // or 0 if we strictly define remaining as 'requests left in the current window'.
      // Given the context of fixed window limits, we assume requests are tracked per window. 
      // If not tracked, they implicitly have access until a request forces tracking. 
      return LIMIT; 
    }

    const { windowStart, count } = entry;

    // Check if the current window is still active relative to nowMs
    let effectiveCount = count;

    if (nowMs - windowStart >= WINDOW_MS) {
        // Window expired. This calculation must reflect that the remaining requests are for a new hypothetical window starting at nowMs.
        // Since allow() manages the actual state updates, this function primarily reads the current tracking status.
        // For safety and consistency in reporting, we rely on the count stored, acknowledging it might be stale if the caller doesn't immediately follow up with allow().
        return LIMIT; // If the window is expired, theoretically all 3 requests are available for a new window.
    }

    return LIMIT - effectiveCount;
  };

  const reset = (key: string): void => {
    state.delete(key);
  };

  return {
    allow,
    remaining,
    reset,
  };
}

