export function createTodoApp(): TodoApp {
  const todos: Todo[] = []
  let nextId: number = 1

  const addTodo = (text: string): Todo => {
    const newTodo: Todo = {
      id: nextId++,
      text: text,
      completed: false,
    }
    todos.push(newTodo)
    return newTodo
  }

  const getTodo = (id: number): Todo | undefined => {
    return todos.find((todo) => todo.id === id)
  }

  const toggleTodo = (id: number): void => {
    const index = todos.findIndex((todo) => todo.id === id)
    if (index !== -1) {
      todos[index].completed = !todos[index].completed
    }
  }

  const deleteTodo = (id: number): boolean => {
    const initialLength = todos.length
    const index = todos.findIndex((todo) => todo.id === id)
    if (index !== -1) {
      // Remove the item
      todos.splice(index, 1)
      return true
    }
    return false
  }

  const listTodos = (): Todo[] => {
    return todos
  }

  const listCompleted = (): Todo[] => {
    return todos.filter((todo) => todo.completed)
  }

  const listPending = (): Todo[] => {
    return todos.filter((todo) => !todo.completed)
  }

  const clearCompleted = (): void => {
    // Filter out completed items
    const pendingTodos = todos.filter((todo) => !todo.completed)

    // Replace the original array with only pending items
    todos.length = 0
    todos.push(...pendingTodos)
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  }
}

