export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  type CacheEntry = {
    value: unknown;
    expiresAt: number;
  };

  private cache = new Map<string, CacheEntry>();

  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const ttl = ttlMs ?? 1000;
    const expiresAt = nowMs + ttl;
    this.cache.set(key, { value, expiresAt });
  }

  get(key: string, nowMs: number): unknown {
    const entry = this.cache.get(key);
    if (!entry) {
      return undefined;
    }
    if (nowMs >= entry.expiresAt) {
      // Entry is expired, treat as non-existent
      return undefined;
    }
    return entry.value;
  }

  has(key: string, nowMs: number): boolean {
    const entry = this.cache.get(key);
    if (!entry) {
      return false;
    }
    // Check expiration
    return nowMs < entry.expiresAt;
  }

  delete(key: string): boolean {
    return this.cache.delete(key);
  }

  size(nowMs: number): number {
    let count = 0;
    for (const entry of this.cache.values()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  }

  clear(): void {
    this.cache.clear();
  }
}

export function createTtlCache(): TtlCache {
  interface CacheEntry {
    value: unknown
    expiresAt: number
  }

  interface TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
    get(key: string, nowMs: number): unknown
    has(key: string, nowMs: number): boolean
    delete(key: string): boolean
    size(nowMs: number): number
    clear(): void
  }

  const cache = new Map<string, CacheEntry>();
  const DEFAULT_TTL = 1000; // milliseconds

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    let expiresAt: number;

    if (ttlMs === 0) {
      expiresAt = nowMs; // Immediate expiration if TTL is 0
    } else {
      // Default TTL is 1000ms
      const effectiveTtl = ttlMs !== undefined ? ttlMs : DEFAULT_TTL;
      expiresAt = nowMs + effectiveTtl;
    }

    cache.set(key, { value, expiresAt });
  };

  const get = (key: string, nowMs: number): unknown => {
    const entry = cache.get(key);
    if (!entry) {
      return undefined; // Key does not exist
    }

    // Check expiration
    if (nowMs >= entry.expiresAt) {
      // Entry is expired. We treat it as if it doesn't exist for retrieval purposes, 
      // although the key might still reside in the map until garbage collection or explicit cleanup.
      // For has/size logic below, this is sufficient. Returning undefined signals staleness.
      return undefined; 
    }

    return entry.value;
  };

  const has = (key: string, nowMs: number): boolean => {
    const entry = cache.get(key);
    if (!entry) {
      return false;
    }

    // Check expiration
    return nowMs < entry.expiresAt;
  };

  const deleteFn = (key: string): boolean => {
    if (!cache.has(key)) {
      return false;
    }
    cache.delete(key);
    return true;
  };

  const size = (nowMs: number): number => {
    let count = 0;
    for (const entry of cache.values()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  };

  const clear = (): void => {
    cache.clear();
  };

  return {
    set,
    get,
    has,
    delete: deleteFn,
    size,
    clear
  } as TtlCache;
}

