export function createTodoApp(): {
    addTodo: (text: string) => { id: number, text: string, completed: boolean },
    getTodo: (id: number) => { id: number, text: string, completed: boolean } | undefined,
    toggleTodo: (id: number) => void,
    deleteTodo: (id: number) => boolean,
    listTodos: () => Array<{ id: number, text: string, completed: boolean }>,
    listCompleted: () => Array<{ id: number, text: string, completed: boolean }>,
    listPending: () => Array<{ id: number, text: string, completed: boolean }>,
    clearCompleted: () => void
} {
    const todos: Array<{ id: number, text: string, completed: boolean }> = [];
    let nextId: number = 1;

    /**
     * Adds a new todo to the list.
     * @param text The text of the new todo.
     * @returns The newly created todo object.
     */
    const addTodo = (text: string): { id: number, text: string, completed: boolean } => {
        const newTodo = {
            id: nextId++,
            text: text,
            completed: false,
        };
        todos.push(newTodo);
        return newTodo;
    };

    /**
     * Retrieves a todo by its ID.
     * @param id The ID of the todo to retrieve.
     * @returns The todo object or undefined if not found.
     */
    const getTodo = (id: number): { id: number, text: string, completed: boolean } | undefined => {
        return todos.find(todo => todo.id === id);
    };

    /**
     * Toggles the completion status of a todo by its ID. Does nothing if ID is not found.
     * @param id The ID of the todo to toggle.
     */
    const toggleTodo = (id: number): void => {
        const todoIndex = todos.findIndex(todo => todo.id === id);
        if (todoIndex !== -1) {
            todos[todoIndex].completed = !todos[todoIndex].completed;
        }
    };

    /**
     * Deletes a todo by its ID.
     * @param id The ID of the todo to delete.
     * @returns True if the todo was successfully deleted, false otherwise.
     */
    const deleteTodo = (id: number): boolean => {
        const initialLength = todos.length;
        // Filter out the item with the matching ID
        const filteredTodos = todos.filter(todo => todo.id !== id);

        if (filteredTodos.length < initialLength) {
            // Item was found and removed
            todos.length = 0; // Clear current array
            todos.push(...filteredTodos); // Rebuild the array without the deleted item
            return true;
        }
        return false;
    };

    /**
     * Lists all todos.
     * @returns An array of all todo objects.
     */
    const listTodos = (): Array<{ id: number, text: string, completed: boolean }> => {
        // Return a copy for immutability context in external usage, though returning the internal array is simpler here.
        return todos;
    };

    /**
     * Lists all completed todos.
     * @returns An array of completed todo objects.
     */
    const listCompleted = (): Array<{ id: number, text: string, completed: boolean }> => {
        return todos.filter(todo => todo.completed);
    };

    /**
     * Lists all pending todos.
     * @returns An array of pending todo objects.
     */
    const listPending = (): Array<{ id: number, text: string, completed: boolean }> => {
        return todos.filter(todo => !todo.completed);
    };

    /**
     * Clears all completed todos from the list.
     */
    const clearCompleted = (): void => {
        // Filter to keep only pending todos
        const pendingTodos = todos.filter(todo => !todo.completed);
        todos.length = 0; // Clear original array
        todos.push(...pendingTodos); // Rebuild with only pending items
    };

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted
    };
}

export function createTodoApp(): TodoApp {
  interface Todo {
    id: number
    text: string
    completed: boolean
  }

  interface TodoApp {
    addTodo(text: string): Todo
    getTodo(id: number): Todo | undefined
    toggleTodo(id: number): void
    deleteTodo(id: number): boolean
    listTodos(): Todo[]
    listCompleted(): Todo[]
    listPending(): Todo[]
    clearCompleted(): void
  }

  const todos: Record<number, Todo> = {}
  let nextId: number = 1

  const addTodo = (text: string): Todo => {
    const newTodo: Todo = { id: nextId++, text, completed: false }
    todos[newTodo.id] = newTodo
    return newTodo
  }

  const getTodo = (id: number): Todo | undefined => {
    return todos[id]
  }

  const toggleTodo = (id: number): void => {
    const todo = todos[id]
    if (todo) {
      todo.completed = !todo.completed
    }
  }

  const deleteTodo = (id: number): boolean => {
    if (todos[id]) {
      delete todos[id]
      return true
    }
    return false
  }

  const listTodos = (): Todo[] => {
    return Object.values(todos)
  }

  const listCompleted = (): Todo[] => {
    return Object.values(todos).filter(todo => todo.completed)
  }

  const listPending = (): Todo[] => {
    return Object.values(todos).filter(todo => !todo.completed)
  }

  const clearCompleted = (): void => {
    const completedIds = Object.keys(todos)
      .filter(idStr => todos[Number(idStr)].completed)
      .map(idStr => Number(idStr))

    for (const id of completedIds) {
      delete todos[id]
    }
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  } as TodoApp
}

