export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();
  const defaultTtlMs = 1000;

  function checkExpiration(expiresAt: number, nowMs: number): boolean {
    return nowMs < expiresAt;
  }

  return {
    /**
     * Sets a key-value pair in the cache with an expiration time.
     */
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs !== undefined ? ttlMs : defaultTtlMs;
      const expiresAt = nowMs + ttl;
      cache.set(key, { value, expiresAt });
    },

    /**
     * Retrieves the value associated with a key if it exists and is not expired.
     */
    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (!entry) {
        return undefined;
      }

      if (checkExpiration(entry.expiresAt, nowMs)) {
        // Entry is expired, treat as if it doesn't exist for retrieval purposes in this context.
        // Note: We don't delete here to keep size/delete operations separate unless explicitly requested.
        return undefined;
      }

      return entry.value;
    },

    /**
     * Checks if a key exists and is not expired.
     */
    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      if (!entry) {
        return false;
      }
      // Check expiration strictly
      return checkExpiration(entry.expiresAt, nowMs);
    },

    /**
     * Deletes a key from the cache. Returns true if the key existed and was deleted.
     */
    delete(key: string): boolean {
      if (!cache.has(key)) {
        return false;
      }
      cache.delete(key);
      return true;
    },

    /**
     * Counts the number of live (non-expired) entries at a given timestamp.
     */
    size(nowMs: number): number {
      let count = 0;
      for (const entry of cache.values()) {
        if (checkExpiration(entry.expiresAt, nowMs)) {
          count++;
        }
      }
      return count;
    },

    /**
     * Removes all entries from the cache.
     */
    clear(): void {
      cache.clear();
    }
  };
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();
  const defaultTtlMs = 1000;

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    const effectiveTtlMs = ttlMs === undefined ? defaultTtlMs : ttlMs;
    const expiresAt = nowMs + effectiveTtlMs;

    // Set or update the entry
    cache.set(key, { value, expiresAt });
  };

  const get = (key: string, nowMs: number): unknown => {
    const entry = cache.get(key);
    if (!entry) {
      return undefined;
    }

    if (nowMs >= entry.expiresAt) {
      // Entry has expired, remove it
      cache.delete(key);
      return undefined;
    }

    return entry.value;
  };

  const has = (key: string, nowMs: number): boolean => {
    const entry = cache.get(key);
    return entry !== undefined && nowMs < entry.expiresAt;
  };

  const deleteKey = (key: string): boolean => {
    const exists = cache.has(key);
    if (exists) {
      cache.delete(key);
      return true;
    }
    return false;
  };

  const size = (nowMs: number): number => {
    let count = 0;
    for (const entry of cache.values()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  };

  const clear = (): void => {
    cache.clear();
  };

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
