export function createEventEmitter() {
    const events = new Map();

    const on = (event: string, listener: (...args: any[]) => void): number => {
        if (!events.has(event)) {
            events.set(event, { listeners: [], onceListeners: [] });
        }
        const eventData = events.get(event)!;
        eventData.listeners.push(listener);
        return eventData.listeners.length;
    };

    const once = (event: string, listener: (...args: any[]) => void): number => {
        if (!events.has(event)) {
            events.set(event, { listeners: [], onceListeners: [] });
        }
        const eventData = events.get(event)!;
        eventData.onceListeners.push({ listener, event });
        return eventData.onceListeners.length;
    };

    const off = (event: string, listener: (...args: any[]) => void): boolean => {
        if (!events.has(event)) {
            return false;
        }
        const eventData = events.get(event)!;

        // Remove from normal listeners
        const normalIndex = eventData.listeners.findIndex(l => l === listener);
        if (normalIndex !== -1) {
            eventData.listeners.splice(normalIndex, 1);
            return true;
        }

        // Remove from one-time listeners
        const onceIndex = eventData.onceListeners.findIndex(l => l.listener === listener && l.event === event);
        if (onceIndex !== -1) {
            eventData.onceListeners.splice(onceIndex, 1);
            return true;
        }

        return false;
    };

    const emit = (event: string, ...args: any[]): any[] => {
        if (!events.has(event)) {
            return [];
        }

        const eventData = events.get(event)!;
        const results = [];

        // Emit normal listeners in registration order
        for (const listener of eventData.listeners) {
            results.push(listener(...args));
        }

        // Emit one-time listeners in registration order
        for (const instance of eventData.onceListeners) {
            results.push(instance.listener(...args));
        }

        return results;
    };

    const listenerCount = (event: string): number => {
        if (!events.has(event)) {
            return 0;
        }
        return events.get(event)!.listeners.length + events.get(event)!.onceListeners.length;
    };

    return {
        on,
        once,
        off,
        emit,
        listenerCount
    };
}

