            // Window reset logic
            data.windowStartMs = Math.floor(nowMs / windowSizeMs) * windowSizeMs;
            data.requestCount = 0;
        }

        data.requestCount++;
    }

    function getWindowInfo(key: string, nowMs: number): { windowStartMs: number, requestCount: number } | null {
        const data = state.get(key);
        if (!data) return null;

        // Check if the current window has elapsed
        if (nowMs >= data.windowStartMs + windowSizeMs) {
            // Window reset logic: update state immediately upon checking if it's expired
            data.windowStartMs = Math.floor(nowMs / windowSizeMs) * windowSizeMs;
            data.requestCount = 0;
        }

        return { windowStartMs: data.windowStartMs, requestCount: data.requestCount };
    }

