export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const store: Record<string, {
    windowStart: number;
    remaining: number;
  }> = {};

  const allow = (key: string, nowMs: number): boolean => {
    if (!(key in store)) {
      store[key] = {
        windowStart: nowMs,
        remaining: limit,
      };
      return true;
    }

    const entry = store[key];

    // Check if the window has expired
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.remaining = limit;
    }

    // Check if quota remains
    if (entry.remaining > 0) {
      entry.remaining--;
      return true;
    } else {
      return false;
    }
  };

  const remaining = (key: string, nowMs: number): number => {
    if (!(key in store)) {
      return limit; // If key is new, it allows the maximum allowed for this window setup, though allow handles initial state setup
    }
    const entry = store[key];

    // Check if the window has expired
    if (nowMs - entry.windowStart >= windowMs) {
      // In a strict implementation, we might reset here too if remaining is 0/negative, but for 'remaining' query, we just update the window start for consistency.
      entry.windowStart = nowMs;
