                normal: [],
                once: []
            };
        }
        return listeners[event];
    };

    function on(event: string, listener: (payload: any) => void): number {
        const eventListeners = getListeners(event);
        eventListeners.normal.push({ type: 'normal', listener });
        return eventListeners.normal.length;
    }

    function once(event: string, listener: (payload: any) => void): number {
        const eventListeners = getListeners(event);
        eventListeners.once.push({ type: 'once', listener });
        return eventListeners.once.length;
    }

    function off(event: string, listener: (payload: any) => void): boolean {
        const eventListeners = getListeners(event);

        if (eventListeners.normal.length === 0 && eventListeners.once.length === 0) {
            return false;
        }

        let removed = false;

        // Check normal listeners
        for (let i = eventListeners.normal.length - 1; i >= 0; i--) {
            if (eventListeners.normal[i].listener === listener) {
                eventListeners.normal.splice(i, 1);
                removed = true;
                break;
            }
        }

        if (removed) {
            return true;
        }

        // Check one-time listeners
        for (let i = eventListeners.once.length - 1; i >= 0; i--) {
            if (eventListeners.once[i].listener === listener) {
                eventListeners.once.splice(i, 1);
                removed = true;
                break;
            }
        }

        return removed;
    }

    function listenerCount(event: string): number {
        const eventListeners = getListeners(event);
        return eventListeners.normal.length + eventListeners.once.length;
    }

    function emit(event: string, payload: any): any[] {
        const eventListeners = getListeners(event);
        const results: any[] = [];

        // Fire normal listeners in registration order
        for (const listener of eventListeners.normal) {
            results.push(listener.listener(payload));
        }

        // Fire one-time listeners in registration order
        for (const listener of eventListeners.once) {
            results.push(listener.listener(payload));
        }

        return results;
    }

    return {
        on,
        once,
        off,
        emit,
        listenerCount
    };
}

export function createEventEmitter(): EventEmitter {
  const listeners: Map<string, { listeners: Array<{ listener: Listener; isOnce: boolean }> }> = new Map();

  const emitEvent = (event: string, payload: unknown): unknown[] => {
    const eventData = listeners.get(event);
    if (!eventData) {
      return [];
    }

    const results: unknown[] = [];
    const listenersToInvoke: Array<{ listener: Listener; isOnce: boolean; index: number }> = [];

    // Collect all current listeners for this event, respecting insertion order
    eventData.listeners.forEach((item, index) => {
      listenersToInvoke.push({ listener: item.listener, isOnce: item.isOnce, index: index });
    });

    for (const { listener, isOnce, index } of listenersToInvoke) {
      if (isOnce) {
        // Mark for removal after invocation by the logic below
        listenersToInvoke.splice(listenersToInvoke.indexOf({ listener, isOnce, index }), 1);
      } else {
        results.push(listener(payload));
      }
    }

    // Remove 'once' listeners that have been invoked
    eventData.listeners = eventData.listeners.filter(item => !item.isOnce || !listenersToInvoke.some(inv => inv.index === eventData.listeners.indexOf(item)));

    return results;
  };

  const on = (event: string, listener: Listener): number => {
    if (!listeners.has(event)) {
      listeners.set(event, { listeners: [] });
    }
    const eventData = listeners.get(event)!;
    eventData.listeners.push({ listener, isOnce: false });
    return eventData.listeners.length;
  };

  const once = (event: string, listener: Listener): number => {
    if (!listeners.has(event)) {
      listeners.set(event, { listeners: [] });
    }
    const eventData = listeners.get(event)!;
    eventData.listeners.push({ listener, isOnce: true });
    return eventData.listeners.length;
  };

  const off = (event: string, listener: Listener): boolean => {
    const eventData = listeners.get(event);
    if (!eventData) {
      return false;
    }

    const initialLength = eventData.listeners.length;
    eventData.listeners = eventData.listeners.filter(item => item.listener !== listener);

    return eventData.listeners.length < initialLength;
  };

  const listenerCount = (event: string): number => {
    return listeners.has(event) ? listeners.get(event)!.listeners.length : 0;
  };

  const emit = (event: string, payload: unknown): unknown[] => {
    if (!listeners.has(event)) {
      return [];
    }
    const eventData = listeners.get(event)!;
    const results: unknown[] = [];

    // Filter out 'once' listeners that have already been called (requires tracking invocation state which is complex for a simple structure, re-evaluating logic for correctness)

    const executionOrderListeners: Array<{ listener: Listener; isOnce: boolean }> = eventData.listeners.map(item => ({ listener: item.listener, isOnce: item.isOnce }));

    for (let i = 0; i < executionOrderListeners.length; i++) {
      const item = executionOrderListeners[i];
      if (!item.isOnce) {
        results.push(item.listener(payload));
      } else {
        // Mark 'once' listener for removal by setting its flag to null/undefined (which will be filtered out later or tracked differently)
        // For simplicity and correctness based on the requirement "once listeners are removed after first invocation", we modify it immediately.
        item.listener = null; // Mark as invoked, effectively removing it from subsequent consideration in this simple model.
      }
    }

    // Rebuild the list excluding null listeners (those that have been 'once' activated)
    eventData.listeners = eventData.listeners.filter(item => item.listener !== null);


    return results;
  };

  const getListenerCount = (event: string): number => {
    return listeners.has(event) ? listeners.get(event)!.listeners.length : 0;
  };


  return {
    on,
    once,
    off,
    emit,
    listenerCount
  };
}

export function createRateLimiter(maxRequests: number = 3, windowMs: number = 1000): {
    allow: (key: string, nowMs: number) => boolean;
    remaining: (key: string, nowMs: number) => number;
    reset: (key: string) => void;
} {
    const limits = new Map<string, {
        requestTimes: number[];
        maxRequests: number;
    }>();

    const processKey = (key: string, nowMs: number): boolean => {
        if (!limits.has(key)) {
            limits.set(key, { requestTimes: [], maxRequests: maxRequests });
            limits.get(key)!.requestTimes.push(nowMs);
            return true;
        }

        const state = limits.get(key)!;
        const windowStartMs = nowMs - windowMs;

        // Filter out requests older than the window
        state.requestTimes = state.requestTimes.filter(t => t >= windowStartMs);

        if (state.requestTimes.length < state.maxRequests) {
            state.requestTimes.push(nowMs);
            return true;
        }

        return false;
    };

    const checkRemaining = (key: string, nowMs: number): number => {
        if (!limits.has(key)) {
            return maxRequests;
        }
        const state = limits.get(key)!;
        const windowStartMs = nowMs - windowMs;

        // Filter out requests older than the window
        state.requestTimes = state.requestTimes.filter(t => t >= windowStartMs);

        return Math.max(0, state.maxRequests - state.requestTimes.length);
    };

    const resetKey = (key: string): void => {
        if (limits.has(key)) {
            limits.delete(key);
        }
    };

    return {
        allow: (key: string, nowMs: number): boolean => processKey(key, nowMs),
        remaining: (key: string, nowMs: number): number => checkRemaining(key, nowMs),
        reset: (key: string): void => resetKey(key),
    };
}

