export type Calculator = {
  add(n: number): any & Calculator;
  subtract(n: number): any & Calculator;
  multiply(n: number): any & Calculator;
  divide(n: number): any & Calculator;
  clear(): any & Calculator;
  result(): number;
  memoryStore(): any & Calculator;
  memoryRecall(): number;
  memoryClear(): any & Calculator;
  memoryAdd(): any & Calculator;
};

class CalculatorState implements Calculator {
  private currentResult: number = 0;
  private memoryValue: number = 0;

  add(n: number): CalculatorState {
    this.currentResult += n;
    return this;
  }

  subtract(n: number): CalculatorState {
    this.currentResult -= n;
    return this;
  }

  multiply(n: number): CalculatorState {
    this.currentResult *= n;
    return this;
  }

  divide(n: number): CalculatorState {
    if (n === 0) {
      // Handle division by zero gracefully, perhaps setting to Infinity or throwing an error, but for simple calculator simulation, we might just set a defined value. Let's handle it as standard JS does.
      this.currentResult /= n;
    } else {
      this.currentResult /= n;
    }
    return this;
  }

  clear(): CalculatorState {
    this.currentResult = 0;
    return this;
  }

  result(): number {
    return this.currentResult;
  }

  memoryStore(): CalculatorState {
    this.memoryValue = this.currentResult;
    return this;
  }

  memoryRecall(): number {
    // Must return memory and not mutate current value
    return this.memoryValue;
  }

  memoryClear(): CalculatorState {
    this.memoryValue = 0;
    return this;
  }

  memoryAdd(): CalculatorState {
    // Adds current value into memory, does NOT change current value
    this.memoryValue += this.currentResult;
    return this;
  }
}

export function createCalculator(): CalculatorState {
  return new CalculatorState();
}

/**
 * Minimal event emitter implementation factory.
 * @returns {object} An object containing event methods: on, once, off, emit, listenerCount.
 */
export function createEventEmitter(): {
    on: (event: string, listener: (...args: any[]) => any) => number;
    once: (event: string, listener: (...args: any[]) => any) => number;
    off: (event: string, listener: (...args: any[]) => void) => boolean;
    emit: (event: string, payload?: any[] | any): Array<any>;
    listenerCount: (event: string) => number;
} {
    // Internal structure to hold listeners for all events.
    // Maps event name -> { regularListeners: ListenerRecord[], onceListeners: ListenerRecord[] }
    const listeners = new Map<string, { 
        regular: Array<{ listener: (...args: any[]) => any }> &, 
        once: Array<{ wrapper: (...args: any[]) => void; originalListener: (...args: any[]) => void }> &
    }>();

    // Helper function to get or initialize the listener storage for an event.
    const _getListeners = (event: string) => {
        if (!listeners.has(event)) {
            listeners.set(event, { regular: [], once: [] });
        }
        return listeners.get(event)!;
    };

    /**
     * Registers a persistent listener for an event.
     */
    const on = (event: string, listener: (...args: any[]) => any): number => {
        if (typeof listener !== 'function') {
            throw new TypeError('Listener must be a function');
        }

        const state = _getListeners(event);
        state.regular.push({ listener });
        return state.regular.length;
    };

    /**
     * Registers a one-time listener for an event.
     */
    const once = (event: string, listener: (...args: any[]) => any): number => {
        if (typeof listener !== 'function') {
            throw new TypeError('Listener must be a function');
        }

        // Wrap the original listener to handle execution and cleanup.
        const wrapper = function(...args: any[]) {
            try {
                const result = listener(...args);

                // Cleanup mechanism: remove this specific entry after successful run
                const state = _getListeners(event);
                state.once = state.once.filter(entry => {
                    // In JS, object references might be tricky here if multiple listeners 
                    // are passed the exact same reference. We assume identity comparison is safe.
                    return entry !== ({ wrapper: this, originalListener: undefined } as any); // Hack to allow unique identification check
                });

                // Find and remove this specific wrapper instance from the array
                const indexToRemove = state.once.indexOf({ wrapper: this, originalListener: listener });
                if (indexToRemove > -1) {
                    state.once.splice(indexToRemove, 1);
                }

                return result;
            } finally {
                 // Ensure cleanup runs even if the listener throws an error
                const state = _getListeners(event);
                state.once = state.once.filter(entry => {
                    return entry !== ({ wrapper: this, originalListener: undefined } as any);
                });
            }
        };

        // Store a unique identifier/wrapper pair for proper removal tracking in off()
        const state = _getListeners(event);
        state.once.push({ wrapper: wrapper as any, originalListener: listener });

        return state.regular.length + state.once.length;
    };

    /**
     * Removes one matching listener for an event.
     * Returns true if a listener was removed, false otherwise.
     */
    const off = (event: string, listener: (...args: any[]) => void): boolean => {
        if (!listeners.has(event)) {
            return false;
        }

        const state = listeners.get(event)!;

        // 1. Check and remove regular listeners
        let removedRegularIndex = state.regular.findIndex(entry => entry.listener === listener);
        if (removedRegularIndex > -1) {
            state.regular.splice(removedRegularIndex, 1);
            return true;
        }

        // 2. Check and remove one-time listeners
        let removedOnceIndex = state.once.findIndex(entry => entry.originalListener === listener);
        if (removedOnceIndex > -1) {
             state.once.splice(removedOnceIndex, 1);
            return true;
        }

        // 3. Optional cleanup: if both arrays are empty, remove the event key entirely
        if (state.regular.length === 0 && state.once.length === 0) {
             listeners.delete(event);
        }

        return false;
    };


    /**
     * Executes all listeners for an event in registration order.
     * Returns an array containing the return value of every listener executed.
     */
    const emit = (event: string, payload?: any[] | any): Array<any> => {
        if (!listeners.has(event)) {
            return [];
        }

        const state = listeners.get(event)!;
        const results: any[] = [];

        // 1. Execute regular listeners (must iterate over a copy since they shouldn't be modified)
        // We execute the actual stored listener function
        [...state.regular].forEach(entry => {
            try {
                results.push((entry.listener as (...args: any[]) => any))(payload);
            } catch (e) {
                results.push(e); // Optionally return errors
            }
        });

        // 2. Execute one-time listeners (Crucially, we must iterate over a copy because execution modifies the state!)
        const onceListenersCopy = [...state.once];
        for (let i = 0; i < onceListenersCopy.length; i++) {
            const entry = onceListenersCopy[i];
            try {
                // The wrapper handles both execution and cleanup of itself from the internal state.
                const result = (entry.wrapper as (...args: any[]) => any)(payload); 
                results.push(result);
            } catch (e) {
                 results.push(e);
            }
        }

        return results;
    };

    /**
     * Gets the current count of listeners for an event.
     */
    const listenerCount = (event: string): number => {
        if (!listeners.has(event)) {
            return 0;
        }
        const state = listeners.get(event)!;
        return state.regular.length + state.once.length;
    };

    return {
        on,
        once,
        off,
        emit,
        listenerCount
    };
}

export type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  // Internal map storing listeners for each event name.
  // Each entry is an array of metadata objects.
  type ListenerEntry = {
    callback: Listener;
    isOnce: boolean;
    fired: boolean; // Tracks if a 'once' listener has been triggered
  };

  const events = new Map<string, ListenerEntry[]>();

  /** Helper function to get or initialize the listener array for an event. */
  function getListeners(event: string): ListenerEntry[] {
    if (!events.has(event)) {
      events.set(event, []);
    }
    return events.get(event)!;
  }

  /** Standard handler for adding a listener. */
  const addListener = (event: string, callback: Listener, isOnce: boolean): number => {
    const listeners = getListeners(event);
    listeners.push({
      callback: callback,
      isOnce: isOnce,
      fired: false,
    });
    return listeners.length;
  };

  /** Standard handler for removing a listener by reference. */
  const removeListener = (event: string, callback: Listener): boolean => {
    const listeners = events.get(event);
    if (!listeners) return false;

    // Find the index of the exact function reference
    for (let i = 0; i < listeners.length; i++) {
      if (listeners[i].callback === callback) {
        listeners.splice(i, 1);
        return true;
      }
    }
    return false;
  };


  const emitter: EventEmitter = {
    /** Adds a listener for the specified event. */
    on(event: string, listener: Listener): number {
      // Duplicate registrations are allowed and tracked independently.
      return addListener(event, listener, false);
    },

    /** Adds a one-time listener for the specified event. */
    once(event: string, listener: Listener): number {
      // One-time listeners are marked internally for removal after firing.
      return addListener(event, listener, true);
    },

    /** Removes a single registration of a listener callback. */
    off(event: string, listener: Listener): boolean {
      if (!events.has(event)) return false;
      return removeListener(event, listener);
    },

    /** 
     * Invokes all registered listeners for the given event.
     * Removes once-shot listeners after invocation.
     */
    emit(event: string, payload: unknown): unknown[] {
      const listeners = events.get(event);
      if (!listeners || listeners.length === 0) {
        return [];
      }

      // We must iterate over a copy of the array indices because we might splice/remove elements
      // (specifically for 'once' listeners) during iteration.
      const results: unknown[] = [];

      // Use reverse index loop to safely handle removal via splicing without messing up subsequent indices.
      for (let i = listeners.length - 1; i >= 0; i--) {
        const entry = listeners[i];

        if (entry.isOnce && entry.fired) {
          // Skip already fired once-time listeners, though theoretically they should be removed below.
          continue; 
        }

        try {
            const result = entry.callback(payload);
            results.push(result);

            // Check for and handle removal of 'once' listeners immediately after execution
            if (entry.isOnce) {
                listeners[i].fired = true; // Mark as fired
                // Remove the listener from the internal array structure
                listeners.splice(i, 1);
                // Since we removed it at index i, and we are iterating backward, 
                // we don't need to adjust i explicitly because the next iteration step (i--) 
                // will correctly jump over the now-missing element space.
            }

        } catch (e) {
            // Optionally handle errors here if required, but generally, emitters allow execution to continue.
            // For this contract, we just capture the results/return values.
        }
      }

      // Since we processed listeners in reverse order and removed them as needed, 
      // 'results' contains the return values of all successful calls.
      return results;
    },

    /** Returns the number of registered listeners for an event. */
    listenerCount(event: string): number {
      const listeners = events.get(event);
      return listeners ? listeners.length : 0;
    }
  };

  return emitter;
}

export function createRateLimiter(): {
    allow: (key: string, nowMs: number) => boolean;
    remaining: (key: string, nowMs: number) => number;
    reset: (key: string) => void;
} {
    /**
     * Internal storage: Key -> { startMs: timestamp of window start, count: requests made in current window }
     */
    const rateLimitStore = new Map<string, { startMs: number; count: number }>();

    const CAPACITY = 3;
    const WINDOW_MS = 1000;

    /**
     * Internal helper to get/reset the state for a given key based on nowMs.
     * This calculates and optionally updates the state, returning the current window capacity tracking object.
     * @param key The key being accessed.
     * @param nowMs Current deterministic timestamp.
     */
    const getCurrentState = (key: string, nowMs: number): { state: { startMs: number; count: number }; hasExpired: boolean } => {
        let storedState = rateLimitStore.get(key);

        if (!storedState) {
            // Never seen key, initialize window starting now
            const newState = { startMs: nowMs, count: 0 };
            rateLimitStore.set(key, newState);
            return { state: newState, hasExpired: true };
        }

        const elapsed = nowMs - storedState.startMs;
        let newState: { startMs: number; count: number };

        if (elapsed >= WINDOW_MS) {
            // Window fully elapsed, reset the counter and set new start time
            newState = { startMs: nowMs, count: 0 };
            rateLimitStore.set(key, newState);
            return { state: newState, hasExpired: true };
        } else {
            // Still within window (or just started)
            newState = storedState;
            return { state: newState, hasExpired: false };
        }
    };

    /**
     * Attempts to allow a request for the given key. Updates internal state upon success or failure 
     * if a reset was necessary due to window expiration.
     */
    const allow = (key: string, nowMs: number): boolean => {
        let currentState;
        let hasExpired;

        // Step 1: Get/reset state based on time passage
        ({ state: currentState, hasExpired } = getCurrentState(key, nowMs));

        if (hasExpired) {
            // New window starts with count 0. The current request makes it 1.
            currentState.count = 1;
            return true;
        } else {
            // Window active
            const remaining = CAPACITY - currentState.count;
            if (remaining > 0) {
                // Allowed: Consume token
                currentState.count += 1;
                return true;
            } else {
                // Rate limited
                return false;
            }
        }
    };

    /**
     * Calculates the remaining capacity for a key without consuming a token or resetting the window state.
     */
    const remaining = (key: string, nowMs: number): number => {
        let storedState = rateLimitStore.get(key);
        if (!storedState) {
            return CAPACITY;
        }

        const elapsed = nowMs - storedState.startMs;

        if (elapsed >= WINDOW_MS) {
            // Window expired, capacity is reset to max (CAPACITY). 
            // We assume the window started exactly at 'nowMs' for calculation purposes.
            return CAPACITY;
        } else {
            // Within window. Remaining = Capacity - Current Count.
            const remainingCount = CAPACITY - storedState.count;
            return Math.max(0, remainingCount); // Ensure it never goes below 0 due to potential timing issues/edge cases
        }
    };

    /**
     * Clears the state for a specific key, effectively resetting rate limits immediately.
     */
    const reset = (key: string): void => {
        rateLimitStore.delete(key);
    };

    return {
        allow,
        remaining,
        reset
    };
}

export function createRateLimiter(): RateLimiter {
    const LIMIT = 3;
    const WINDOW_MS = 1000;

    interface KeyState {
        windowStart: number;
        count: number;
    }

    // Stores state for each unique key. State tracks the window start time and current count.
    const keyStates = new Map<string, KeyState>();

    /**
     * Retrieves or initializes the state for a given key, ensuring that the state respects window boundaries.
     * Performs necessary window resets if the elapsed time exceeds WINDOW_MS.
     * @param key The identifier key.
     * @param nowMs Current time in milliseconds.
     * @returns A mutable reference to the KeyState.
     */
    const getAndUpdateState = (key: string, nowMs: number): KeyState => {
        let state = keyStates.get(key);

        if (!state) {
            // Initialize new key state
            state = { windowStart: nowMs, count: 0 };
            keyStates.set(key, state);
            return state;
        }

        // Check for window boundary reset
        const elapsed = nowMs - state.windowStart;
        if (elapsed >= WINDOW_MS) {
            // Window expired, reset state to the current time
            state.windowStart = nowMs;
            state.count = 0;
            keyStates.set(key, state);
        }
        return state;
    };

    /**
     * Checks if an action is allowed for the given key at the specified time.
     * @param key The unique identifier key.
     * @param nowMs Current time in milliseconds.
     * @returns True if allowed, false otherwise.
     */
    const allow = (key: string, nowMs: number): boolean => {
        // Ensure state is current and potentially reset
        let state = getAndUpdateState(key, nowMs);

        if (state.count < LIMIT) {
            // Allow access and increment count
            state.count++;
            return true;
        } else {
            // Rate limited
            return false;
        }
    };

    /**
     * Calculates the remaining quota for a key at the specified time.
     * @param key The unique identifier key.
     * @param nowMs Current time in milliseconds.
     * @returns The number of remaining allowed attempts (min 0).
     */
    const remaining = (key: string, nowMs: number): number => {
        // Ensure state is current and potentially reset
        let state = getAndUpdateState(key, nowMs);

        return Math.max(0, LIMIT - state.count);
    };

    /**
     * Removes all recorded state for a specific key, simulating a manual refresh or bypass.
     * @param key The unique identifier key to reset.
     */
    const reset = (key: string): void => {
        keyStates.delete(key);
    };

    return {
        allow,
        remaining,
        reset,
    } as RateLimiter;
}

