         * @param text The content of the new todo.
         * @returns The full created Todo object.
         */
        addTodo(text: string): Todo {
            const newTodo: Todo = {
                id: nextId++,
                text: text,
                completed: false,
            };
            todos.push(newTodo);
            // Return a copy to prevent external mutation of the internal state if needed, 
            // though for simplicity and compliance with typical JS patterns, returning the reference is fine here.
            return { ...newTodo };
        },

        /**
         * Retrieves a todo by its ID.
         * @param id The ID of the desired todo.
         * @returns The Todo object if found, otherwise undefined.
