         * @param id The ID of the todo to toggle. Does nothing if the ID is not found.
         */
        toggleTodo(id: number): void {
            const index = todos.findIndex(todo => todo.id === id);
            if (index !== -1) {
                // Mutate state directly
                todos[index] = {
                    ...todos[index], 
                    completed: !todos[index].completed
                };
            }
        },

        /**
         * Deletes a todo item by its ID.
         * @param id The ID of the todo to delete.
         * @returns True if the todo was deleted, false otherwise.
         */
        deleteTodo(id: number): boolean {
            const initialLength = todos.length;
            // Using filter and reassignment is safer for internal state manipulation 
            // than splice if indices might be complex, but since we are looking by ID, 
            // findIndex/splice combination is efficient enough here, provided we handle the return value correctly.
            const index = todos.findIndex(todo => todo.id === id);
            if (index !== -1) {
                todos.splice(index, 1);
                return true;
            }
            return false;
        },

        /**
         * Lists all currently stored todo items.
         * @returns A shallow copy of the entire list of todos.
         */
        listTodos(): Array<Todo> {
            // Return a filtered/copied version to prevent external direct mutation of internal state
            return [...todos]; 
        },

        /**
         * Lists all completed todo items.
         * @returns A shallow copy of the array of completed todos.
         */
        listCompleted(): Array<Todo> {
            return todos.filter(todo => todo.completed);
        },

        /**
         * Lists all pending (incomplete) todo items.
         * @returns A shallow copy of the array of pending todos.
         */
        listPending(): Array<Todo> {
            return todos.filter(todo => !todo.completed);
        },

        /**
         * Removes all completed todo items from the list.
         */
        clearCompleted(): void {
            // Filter and reassign the state array to remove all completed items.
            todos = todos.filter(todo => !todo.completed);
        }
    };
