  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  /**
   * Internal storage map. Key maps to an object containing the value and its expiration timestamp.
   */
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    /**
     * Sets a key-value pair with optional time-to-live (TTL).
     * The current entry is overwritten, and the expiration time is refreshed.
     */
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = typeof ttlMs === 'undefined' ? 1000 : Number(ttlMs);
      if (isNaN(ttl) || ttl < 0) {
        // Handle invalid TTL by setting a very high expiration far in the future or treating it as perpetual for safety
        // Based on requirements, we assume valid number inputs, but defensive programming is good. Let's just treat it based on provided logic.
      }

      const expiresAt = nowMs + (ttl > 0 ? ttl : 1000);

      cache.set(key, { value, expiresAt });
    },

    /**
     * Retrieves the value associated with a key if it has not expired by `nowMs`.
     * Returns undefined if the key is not found or if it has expired.
     */
    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);

      if (!entry || nowMs >= entry.expiresAt) {
        // Simulate deletion of expired entries on access (optional optimization/cleanup)
        if (entry && nowMs >= entry.expiresAt) {
          cache.delete(key);
        }
        return undefined; // Explicitly return unknown type as per required signature, implying absence.
      }

      return entry.value;
    },

    /**
     * Checks if the key exists and is currently live (not expired) at `nowMs`.
     */
    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);

      if (!entry || nowMs >= entry.expiresAt) {
        return false;
      }

      return true;
    },

    /**
     * Deletes an entry and returns true if the key existed before deletion, false otherwise.
     */
    delete(key: string): boolean {
      if (cache.has(key)) {
        // Note: We delete it from the map regardless of its current expiration status.
        return cache.delete(key);
      }
      return false;
    },

    /**
     * Counts the number of entries that are currently live (not expired) at `nowMs`.
     */
    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of cache.entries()) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
          // Optional cleanup while counting expired items
          cache.delete(key);
        }
      }
      return count;
    },

    /**
     * Removes all entries from the cache storage.
     */
    clear(): void {
      cache.clear();
    }
  };
}

export function createTtlCache(): TtlCache {
    // Internal storage: key -> { value: unknown, expiresAt: number }
    const cache = new Map<string, { value: unknown; expiresAt: number }>();

    /**
     * Checks if an entry is expired relative to the given time.
     */
    const isExpired = (expiresAt: number, nowMs: number): boolean => {
        return nowMs >= expiresAt;
    };

    /**
     * Retrieves a value from the cache only if it has not expired.
     * If expired or missing, returns undefined.
     */
    const safeGet = (key: string, nowMs: number): unknown | undefined => {
        const entry = cache.get(key);
        if (!entry) return undefined;

        if (isExpired(entry.expiresAt, nowMs)) {
            // Found expired entry, treat as if it was never there and clean it up.
            cache.delete(key);
            return undefined;
        }
        return entry.value;
    };

    const TtlCache: TtlCache = {
        /**
         * Sets a value in the cache, refreshing its expiration time.
         * @param key The unique identifier for the entry.
         * @param value The value to store (can be undefined).
         * @param nowMs The current timestamp in milliseconds.
         * @param ttlMs Optional Time To Live in milliseconds. If omitted, 1000ms is used.
         */
        set(key, value, nowMs, ttlMs) {
            let effectiveTtlMs: number;

            if (typeof ttlMs !== 'undefined') {
                // Use the provided TTL explicitly (handles 0 or negative if passed)
                effectiveTtlMs = Math.max(0, Number(ttlMs));
            } else {
                // Fixed default TTL is 1000ms
                effectiveTtlMs = 1000;
            }

            const expiresAt = nowMs + effectiveTtlMs;

            cache.set(key, { value: value, expiresAt: expiresAt });
        },

        /**
         * Gets the cached value associated with the key if it has not expired.
         * @param key The identifier of the entry.
         * @param nowMs The current timestamp in milliseconds.
         * @returns The stored value, or undefined if expired/missing.
         */
        get(key, nowMs) {
            const result = safeGet(key, nowMs);
            // TypeScript casting for unknown is necessary since the interface uses unknown return type
            return result as unknown; 
        },

        /**
         * Checks if a key exists and has not expired.
         * @param key The identifier of the entry.
         * @param nowMs The current timestamp in milliseconds.
         * @returns true if the entry exists and is active, false otherwise.
         */
        has(key, nowMs): boolean {
            const entry = cache.get(key);

            if (!entry) {
                return false;
            }

            // Check expiration
            if (nowMs >= entry.expiresAt) {
                cache.delete(key); // Clean up expired entry immediately
                return false;
            }
            return true;
        },

        /**
         * Deletes a key from the cache if it exists.
         * @param key The identifier of the entry to remove.
         * @returns true if an entry was removed, false otherwise.
         */
        delete(key): boolean {
            if (!cache.has(key)) {
                return false;
            }
            const deleted = cache.get(key); 
            // We must check if the item exists AND hasn't expired right before deleting/returning true
            // Since has() cleans up on lookup, we rely on Map API here.
            if (cache.delete(key)) {
                return true;
            }
            return false; // Should theoretically not happen if initial check passes
        },

        /**
         * Counts the number of non-expired entries currently stored in the cache.
         * @param nowMs The current timestamp in milliseconds.
         * @returns The count of active entries.
         */
        size(nowMs): number {
            let count = 0;
            const keysToDelete: string[] = [];

            for (const [key, entry] of cache.entries()) {
                if (isExpired(entry.expiresAt, nowMs)) {
                    keysToDelete.push(key);
                } else {
                    count++;
                }
            }

            // Clean up all expired entries found during size calculation
            for (const key of keysToDelete) {
                cache.delete(key);
            }

            return count;
        },

        /**
         * Clears all entries from the cache.
         */
        clear() {
            cache.clear();
        }
    };

    return TtlCache;
}

