/**
 * @typedef {object} CalculatorApi
 * The chainable API returned by createCalculator().
 */

/**
 * Creates a calculator instance with persistent internal state for current value and memory.
 * 
 * All methods that modify state are designed to return the calculator instance itself,
 * enabling method chaining. Setters must be followed by an arithmetic or memory method.
 * Getters (result(), memoryRecall()) return primitives (number) and effectively terminate the chain.
 *
 * @returns {CalculatorApi} A new, initialized calculator API object.
 */
export const createCalculator = (): CalculatorApi => {
    let currentValue: number = 0;
    let memoryValue: number = 0;

    /**
     * Adds a number to the current value and returns the calculator instance for chaining.
     * @param n The number to add.
     * @returns {CalculatorApi} The updated calculator instance.
     */
    const add = (n: number): CalculatorApi => {
        currentValue += n;
        return apiInstance;
    };

    /**
     * Subtracts a number from the current value and returns the calculator instance for chaining.
     * @param n The number to subtract.
     * @returns {CalculatorApi} The updated calculator instance.
     */
    const subtract = (n: number): CalculatorApi => {
        currentValue -= n;
        return apiInstance;
    };

    /**
     * Multiplies the current value by a factor and returns the calculator instance for chaining.
     * @param n The multiplier.
     * @returns {CalculatorApi} The updated calculator instance.
     */
    const multiply = (n: number): CalculatorApi => {
        currentValue *= n;
        return apiInstance;
    };

    /**
     * Divides the current value by a divisor and returns the calculator instance for chaining. 
     * Handles division by zero by returning NaN.
     * @param n The divisor.
     * @returns {CalculatorApi} The updated calculator instance.
     */
    const divide = (n: number): CalculatorApi => {
        if (n === 0) {
            currentValue = NaN; // Standard behavior for division by zero in JS/TS arithmetic context
        } else {
            currentValue /= n;
        }
        return apiInstance;
    };

    /**
     * Resets the current calculation value to zero and returns the calculator instance for chaining.
     * @returns {CalculatorApi} The calculator instance with reset value.
     */
    const clear = (): CalculatorApi => {
        currentValue = 0;
        return apiInstance;
    };

    /**
     * Retrieves the maximum current calculated result value.
     * Does NOT change state. Returns a primitive number, terminating any active chain.
     * @returns {number} The current calculated result.
     */
    const result = (): number => currentValue;

    /**
     * Stores the current calculation value into memory and returns the calculator instance for chaining.
     * @returns {CalculatorApi} The updated calculator instance.
     */
    const memoryStore = (): CalculatorApi => {
        memoryValue = currentValue;
        return apiInstance;
    };

    /**
     * Adds the current calculation value to the stored memory value (accumulator) 
     * and returns the calculator instance for chaining. Memory is updated but does not change current value.
     * @returns {CalculatorApi} The updated calculator instance.
     */
    const memoryAdd = (): CalculatorApi => {
        memoryValue += currentValue;
        return apiInstance;
    };

    /**
     * Resets the stored memory value to zero and returns the calculator instance for chaining.
     * @returns {CalculatorApi} The updated calculator instance.
     */
    const memoryClear = (): CalculatorApi => {
        memoryValue = 0;
        return apiInstance;
    };

    /**
     * Retrieves the stored cumulative memory value.
     * Does NOT change current or memory state. Returns a primitive number, terminating any active chain.
     * @returns {number} The currently stored memory value.
     */
    const memoryRecall = (): number => memoryValue;

    // Assigning functions to an object structure and ensuring proper scope return type inference
    // that all mutating methods return the API object for chaining, while getters return numbers.
    /** @type {CalculatorApi} */
    const apiInstance: CalculatorApi = {
        add: add,
        subtract: subtract,
        multiply: multiply,
        divide: divide,
        clear: clear,

        result: result,

        memoryStore: memoryStore,
        memoryAdd: memoryAdd,
        memoryClear: memoryClear,

        memoryRecall: memoryRecall
    };

    // To satisfy TypeScript type checking that this object is mutable and self-referential for optimal chaining experience,
    // we cast the result to ensure all methods return `apiInstance`.
    return apiInstance as CalculatorApi;
};

