    this._currentValue = 0;
    // Memory remains untouched when clear is called.
    return this;
  }

  result(): number {
    return this._currentValue;
  }

  memoryStore(): Calculator {
    // Current value state is stored into memory, but the current calculator result remains unchanged.
    this._memory = this._currentValue;
    return this;
  }

  /**
   * Recalls the stored memory value without changing the current calculator state.
   */
  memoryRecall(): number {
    // Must return memory and not mutate current result.
    return this._memory;
  }

  memoryClear(): Calculator {
    this._memory = 0;
    return this;
  }

  /**
   * Adds the current calculator value to the stored memory, but does NOT change the current calculator state.
   */
  memoryAdd(): Calculator {
    this._memory += this._currentValue;
    // Current value remains unchanged.
    return this;
  }
}


export function createCalculator(): Calculator {
  return new BasicCalculator();
}

type Listener = (...args: any[]) => any;

/**
 * Manages a set of event-driven functions, allowing registration, removal, and emission.
 */
export function createEventEmitter(): {
    on: (event: string, listener: Listener) => number;
    once: (event: string, listener: Listener) => number;
    off: (event: string, listener: Listener): boolean;
    emit: (event: string, ...payload: any[]): any[];
    listenerCount: (event: string) => number;
} {
    // Internal structure to hold event state.
    // Each entry stores an array of listeners and tracks if they are one-shot functions.
    private events = new Map<string, {
        listeners: Array<{ callback: Listener, isOneShot: boolean }>;
    }>();

    /**
     * Retrieves or initializes the event registry for a given event name.
     * @param eventName The name of the event.
     * @returns The EventRegistry object reference.
     */
    private getEvent(eventName: string) {
        if (!this.events.has(eventName)) {
            this.events.set(eventName, { listeners: [] });
        }
        return this.events.get(eventName)!;
    }

    /**
     * Registers a standard listener (persistent).
     */
    const on = (event: string, listener: Listener): number => {
        const eventState = this.getEvent(event);
        eventState.listeners.push({ callback: listener, isOneShot: false });
        return eventState.listeners.length;
    };

    /**
     * Registers a one-time listener (removes itself after the first successful emission).
     */
    const once = (event: string, listener: Listener): number => {
        const eventState = this.getEvent(event);
        eventState.listeners.push({ callback: listener, isOneShot: true });
        return eventState.listeners.length;
    };

    /**
     * Removes one matching listener by reference.
     * @returns True if a listener was found and removed, otherwise false.
     */
    const off = (event: string, listener: Listener): boolean => {
        const eventState = this.events.get(event);
        if (!eventState) return false;

        // Find the index of the first matching listener callback reference
        for (let i = 0; i < eventState.listeners.length; i++) {
            const item = eventState.listeners[i];
            // Use strict comparison for function references
            if (item.callback === listener) {
                eventState.listeners.splice(i, 1);
                return true;
            }
        }
        return false;
    };

    /**
     * Fires all registered listeners in the order they were added.
     * One-time listeners are automatically removed after execution.
     */
    const emit = (event: string, ...payload: any[]): any[] => {
        const eventState = this.events.get(event);
        if (!eventState || eventState.listeners.length === 0) {
            return [];
        }

        // We iterate using a standard array index/pointer for safe removal during iteration.
        let results: any[] = [];
        const listenersToRun = [...eventState.listeners]; // Create a copy to safely manipulate the original list and avoid issues with 'once' cleanup pointer logic.
        const removedIndices: number[] = [];

        for (let i = 0; i < listenersToRun.length; i++) {
            const item = listenersToRun[i];
            try {
                // Execute the listener, capturing its return value
                results.push(item.callback(...payload));
            } catch (e) {
                // Handle potential errors during execution if necessary, but for this minimal API, we just let it propagate normally.
                throw e;
            }

            // Cleanup check: If the listener was one-shot, mark its index for deletion *after* the loop completes all current emissions.
            if (item.isOneShot) {
                removedIndices.push(i);
            }
        }

        // After running all listeners, remove any that were marked as one-shot.
        // We must iterate backward to maintain correct indices when splicing/removing elements.
        for (let i = removedIndices.length - 1; i >= 0; i--) {
            const indexToRemove = removedIndices[i];
            if (indexToRemove < eventState.listeners.length) {
                 // Check if the item at this index is indeed one-shot before removing it, 
                // although in theory, due to how we populate removedIndices it should be correct.
                const itemToActuallyRemove = eventState.listeners[indexToRemove];
                if (itemToActuallyRemove && itemToActuallyRemove.isOneShot) {
                    eventState.listeners.splice(indexToRemove, 1);
                }
            }
        }

        return results;
    };


    /**
     * Returns the total number of listeners registered for a given event.
     */
    const listenerCount = (event: string): number => {
        const eventState = this.events.get(event);
        return eventState ? eventState.listeners.length : 0;
    };

    return { on, once, off, emit, listenerCount };
}

