     * @returns The current count of listeners for the event after addition.
     */
    const on = (event: string, listener: Listener): number => {
        const listeners = getListenersForEvent(event);
        listeners.push({ callback: listener, isOnce: false });
        return listeners.length;
    };

    /**
     * Attaches a listener that will be automatically removed after the first call.
     * @returns The current count of listeners for the event after addition.
     */
    const once = (event: string, listener: Listener): number => {
        const listeners = getListenersForEvent(event);
        listeners.push({ callback: listener, isOnce: true });
        return listeners.length;
    };

