        if (!events.has(event)) {
            return false;
        }

        let listeners = events.get(event)!;
        for (let i = 0; i < listeners.length; i++) {
            // Comparing function references for exact match
            if (listeners[i].callback === listener) {
                // Remove the first match found and update the stored array
                listeners.splice(i, 1);
                return true;
            }
        }
        return false;
    };

    /**
     * Invokes all listeners for a given event in order. Once listeners are executed,
     * one-time listeners are removed.
     * @returns An array containing the return value of every executed listener.
     */
    const emit = (event: string, payload: unknown): unknown[] => {
        if (!events.has(event)) {
            return [];
        }

        // Work on a copy to allow modification during iteration/cleanup
        let listeners = events.get(event)!;
        const results: unknown[] = [];
        const finishedIndices: Set<number> = new Set(); // Track indices of listeners that executed and need cleanup

        // Iterate using index because removal logic is involved
        for (let i = 0; i < listeners.length; i++) {
            const listenerRegistration = listeners[i];
            try {
                // Execute the callback
                const result = listenerRegistration.callback(payload);
                results.push(result);

                // If it was a 'once' listener, mark it for removal
                if (listenerRegistration.isOnce) {
                    finishedIndices.add(i);
                }
            } catch (e) {
                // Do not propagate runtime errors from listeners during emit cycle, just continue
                console.error(`Error executing event '${event}' listener at index ${i}:`, e);
            }
        }

        // Cleanup step: Remove all one-time listeners that were just called
        if (finishedIndices.size > 0) {
             let cleanIndex = 0;
             while (cleanIndex < finishedIndices.size && cleanIndex < listeners.length) {
                 const actualIndexToDelete = Array.from(finishedIndices).sort((a, b) => b - a);
                 if (activeDeleteIndex === 0) activeDeleteIndex++; // Initial dummy setup for the loop logic below

             }
             // More robust removal: rebuild the array excluding indices marked by finishedIndices
             const newListeners: RegisteredListener[] = [];
             for (let i = 0; i < listeners.length; i++) {
                 if (!finishedIndices.has(i)) {
                     newListeners.push(listeners[i]);
                 }
             }
             events.set(event, newListeners);
        }

        return results;
    };

    /**
     * Gets the total number of listeners registered for an event.
     * @returns The count of listeners.
     */
    const listenerCount = (event: string): number => {
        if (!events.has(event)) {
            return 0;
        }
        return events.get(event)!.length;
    };

    // Return the object implementing the EventEmitter interface
    return {
        on,
        once,
        off,
        emit,
        listenerCount
    } as EventEmitter;
}

/**
 * Factory function that creates a rate limiter object supporting per-key fixed window throttling.
 * Rate policy: 3 requests allowed per 1000ms (1 second) fixed window.
 * Deterministic timestamps (nowMs) must be passed for all operations.
 */
export function createRateLimiter(): {
    allow: (key: string, nowMs: number) => boolean;
    remaining: (key: string, nowMs: number) => number;
    reset: (key: string) => void;
} {
    // State storage for per-key rate limits.
    // Map structure: key -> { count: number, windowStartMs: number }
    const store = new Map<string, { count: number; windowStartMs: number }>();

    const RATE_LIMIT_COUNT = 3;
    const WINDOW_MS = 1000;

    /**
     * Calculates the deterministic start time for the fixed 1000ms window containing nowMs.
     */
    const getWindowStart = (nowMs: number): number => {
        return Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;
    };

    /**
     * Retrieves or initializes the rate limiting state for a given key and timestamp,
     * ensuring it aligns with the fixed window boundary calculation.
     */
    const getOrCreateState = (key: string, nowMs: number): { count: number; windowStartMs: number } => {
        const currentWindowStart = getWindowStart(nowMs);

        // Check if state exists and is relevant to the required fixed window.
        let state = store.get(key);

        if (!state || state.windowStartMs !== currentWindowStart) {
            // State is missing or belongs to a different fixed window, so we reset it.
            state = { count: 0, windowStartMs: currentWindowStart };
            store.set(key, state);
        }

        return state;
    };

    /**
     * Attempts to consume one request quota for a key within the specified time window.
     * @param key The identifier for the resource or user.
     * @param nowMs Deterministic timestamp in milliseconds.
     * @returns True if the request is allowed, false otherwise.
     */
    const allow = (key: string, nowMs: number): boolean => {
        const state = getOrCreateState(key, nowMs);

        if (state.count < RATE_LIMIT_COUNT) {
            // Request allowed: Increment count for the current window.
            state.count += 1;
            return true;
        }

        // Limit hit.
        return false;
    };

    /**
     * Reports how many requests remain allowed for a key within the current window.
     * @param key The identifier for the resource or user.
     * @param nowMs Deterministic timestamp in milliseconds.
     * @returns The remaining request count (never negative).
     */
    const remaining = (key: string, nowMs: number): number => {
        // We must calculate the state based on the current time to determine remaining quota accurately.
        try {
            const state = getOrCreateState(key, nowMs);
            return Math.max(0, RATE_LIMIT_COUNT - state.count);
        } catch (e) {
             // Should ideally not happen with Map access but defensive coding practice.
             return 0;
        }
    };

    /**
     * Clears the rate limiting account and state for a specific key.
     * @param key The identifier to reset.
     */
    const reset = (key: string): void => {
        store.delete(key);
    };


    return {
        allow,
        remaining,
        reset,
    };
}

// Internal state map: Key -> { count: number, windowStart: number }
type RateLimiterState = Map<string, { count: number; windowStart: number }>;

/**
 * Creates a rate limiter instance using fixed-window per key policy.
 * @returns A RateLimiter object adhering to the defined interface.
 */
export function createRateLimiter(): RateLimiter {
    const state: RateLimiterState = new Map();

    // Fixed Policy Constants
    const LIMIT = 3;
    const WINDOW_MS = 1000;

    /**
     * Checks if a request is allowed for the given key at the current time.
     * Resets the window and count upon success, or returns false if rate limited.
     */
    const allow = (key: string, nowMs: number): boolean => {
        let stateEntry = state.get(key);

        // Handle uninitialized keys or check for window expiration/reset
        if (!stateEntry) {
            // Initialize new key's window
            state.set(key, { count: 1, windowStart: nowMs });
            return true;
        } else {
             // Check boundary reset rule
            const elapsed = nowMs - stateEntry.windowStart;

            if (elapsed >= WINDOW_MS) {
                // Window expired -> Fresh start
                state.set(key, { count: 1, windowStart: nowMs });
                return true;
            } else {
                // Within current window
                if (stateEntry.count < LIMIT) {
                    // Success, increment count
                    const newCount = stateEntry.count + 1;
                    state.set(key, { count: newCount, windowStart: stateEntry.windowStart });
                    return true;
                } else {
                    // Rate limited
                    return false;
                }
            }
        }
    };

    /**
     * Returns the remaining quota for the key, respecting window boundaries but only calculating
     * based on current virtual state without changing it (unless reset is called).
     */
    const remaining = (key: string, nowMs: number): number => {
        let stateEntry = state.get(key);

        if (!stateEntry) {
            // If not found, the full limit remains for a new window starting at `nowMs`
            return LIMIT;
        }

        // Check boundary reset rule based on current time
        const elapsed = nowMs - stateEntry.windowStart;

        if (elapsed >= WINDOW_MS) {
            // Window expired, quota resets to full limit minus the consumption of this call 
            // if we were forced to assume 'allow' was called prior to checking remaining, 
            // but since we are only reporting potential remaining use within a *new* window, 
            // it should be LIMIT.
             return LIMIT;
        }

        // Still inside the window: calculate remaining = Limit - Current Count
        const currentRemaining = Math.max(0, LIMIT - stateEntry.count);

        return currentRemaining;
    };

    /**
     * Removes all state associated with a specific key.
     */
    const reset = (key: string): void => {
        state.delete(key);
    };


    return {
        allow: allow,
        remaining: remaining,
        reset: reset
    } satisfies RateLimiter;
}

interface RateLimiter {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
}

