type Todo = { id: number; text: string; completed: boolean };

/**
 * Creates a factory for managing ToDo items with encapsulated state.
 * @returns An object containing methods to interact with the todo list.
 */
export function createTodoApp() {
    // Using a Map enforces unique IDs and provides O(1) access/update/delete by ID.
    /**
     * Internal store for all todos. Key: id, Value: Todo object.
     */
    const todoStore = new Map<number, Todo>();

    // Tracks the next available auto-incrementing ID. Never reused after deletion.
    let nextId: number = 1;

    /**
     * Adds a new todo item to the list.
     * @param text The content of the todo.
     * @returns The full object representation of the created todo.
     */
    const addTodo = (text: string): Todo => {
        if (!text) throw new Error("Todo text cannot be empty.");

        const newTodo: Todo = {
            id: nextId,
            text: text,
            completed: false,
        };

        todoStore.set(newTodo.id, newTodo);
        nextId += 1;

        return { ...newTodo }; // Return a copy as required
    };

    /**
     * Retrieves a todo item by its unique ID.
     * @param id The ID of the todo to retrieve.
     * @returns The todo object, or undefined if not found.
     */
    const getTodo = (id: number): Todo | undefined => {
        return todoStore.get(id);
    };

    /**
     * Toggles the completed status of a specified todo item.
     * If the ID does not exist, it does nothing and does not throw.
     * @param id The ID of the todo to toggle.
     */
    const toggleTodo = (id: number): void => {
        const todo = todoStore.get(id);
        if (todo) {
            // Since we are updating state in a Map, we retrieve the current object, modify it, and set it back.
            todoStore.set(id, { ...todo, completed: !todo.completed });
        }
    };

    /**
     * Deletes a todo item from the list by its ID.
     * @param id The ID of the todo to delete.
     * @returns True if the todo was found and deleted, false otherwise.
     */
    const deleteTodo = (id: number): boolean => {
        return todoStore.delete(id);
    };

    /**
     * Lists all todos currently stored in the application state.
     * @returns An array of all Todo objects.
     */
    const listTodos = (): Array<Todo> => {
        // Convert the Map values iterator to an array and return copies.
        return [...todoStore.values()];
    };

    /**
     * Lists all todo items that are marked as completed.
     * @returns An array of completed Todo objects.
     */
    const listCompleted = (): Array<Todo> => {
        return [...todoStore.values()].filter((todo): todo is Todo => todo.completed);
    };

    /**
     * Lists all todo items that are currently incomplete (pending).
     * @returns An array of pending Todo objects.
     */
    const listPending = (): Array<Todo> => {
        return [...todoStore.values()].filter((todo): todo is Todo => !todo.completed);
    };

    /**
     * Permanently removes all completed todo items from the store.
     * This operation does not affect pending items or the ID counter.
     */
    const clearCompleted = (): void => {
        // Filter out and remove entries where completed is true, effectively clearing them without mutations during iteration/filtering state changes.
        let removedCount = 0;
        for (const [id, todo] of todoStore.entries()) {
            if (todo.completed) {
                todoStore.delete(id);
                removedCount++;
            }
        }
    };

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted,
    };
}

export function createTodoApp(): TodoApp {
  // Internal state mimicking private fields in languages supporting them
  const todos: Todo[] = [];
  let nextId: number = 1;

  /**
   * Adds a new todo item to the list.
   * @param text The content of the todo.
   * @returns The newly created Todo object.
   */
  const addTodo = (text: string): Todo => {
    if (!text) return null; // Basic validation, though contract implies string input

    const newTodo: Todo = {
      id: nextId++,
      text: text,
      completed: false,
    };
    todos.push(newTodo);
    return newTodo;
  };

  /**
   * Retrieves a todo by ID.
   * @param id The ID of the todo to fetch.
   * @returns The Todo object if found, otherwise undefined.
   */
  const getTodo = (id: number): Todo | undefined => {
    return todos.find(todo => todo.id === id);
  };

  /**
   * Toggles the completion status of a todo item.
   * Does nothing if the ID is not found.
   * @param id The ID of the todo to toggle.
   */
  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) {
      // Since objects passed around are references, we can modify the state directly
      // However, for functional purity in a large application, replacement is better.
      // Given the scope constraints, direct mutation of the found object reference within 'todos' array is efficient enough here.
      todo.completed = !todo.completed;
    }
  };

  /**
   * Deletes a todo item by ID.
   * @param id The ID of the todo to delete.
   * @returns True if the todo was found and deleted, false otherwise.
   */
  const deleteTodo = (id: number): boolean => {
    const initialLength = todos.length;
    // Filter is used here to simulate removing an element from the state array immutably relative to the local scope.
    // We must reassign 'todos' which modifies the private state reference.
    const newTodos = todos.filter(todo => todo.id !== id);

    if (newTodos.length < initialLength) {
      // Update the internal state array with the filtered result
      Object.assign(todos, newTodos); 
      return true;
    }
    return false;
  };

  /**
   * Lists all current todo items.
   */
  const listTodos = (): Todo[] => {
    // Returns a shallow copy to prevent external modification from hitting the internal state
    return [...todos]; 
  };

  /**
   * Lists all completed todo items.
   */
  const listCompleted = (): Todo[] => {
    return todos.filter(todo => todo.completed);
  };

  /**
   * Lists all pending (incomplete) todo items.
   */
  const listPending = (): Todo[] => {
    return todos.filter(todo => !todo.completed);
  };

  /**
   * Removes all completed todos from the state.
   */
  const clearCompleted = (): void => {
    // Filter and replace references to ensure internal state consistency based on 'clearCompleted' rule
    Object.assign(todos, todos.filter(todo => !todo.completed));
  };


  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  } as TodoApp;
}

