export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  // Internal store structure: key -> { value: unknown; expiresAt: number }
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  /** Helper to check if an entry is still active at the given timestamp. */
  const isActive = (expiresAt: number, nowMs: number): boolean => {
    return nowMs < expiresAt;
  };

  return {
    /**
     * Sets a value in the cache, overriding any existing key and resetting TTL.
     */
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const defaultTtl = 1000;
      const effectiveTtl = ttlMs === undefined ? defaultTtl : ttlMs;

      if (effectiveTtl <= 0) {
        // If TTL is zero or negative, treat it as expiring immediately without setting expiration time
        // We still record it just to ensure 'delete' works deterministically if set later.
        cache.set(key, { value: value, expiresAt: nowMs });
        return;
      }

      const expiresAt = Math.floor(nowMs + effectiveTtl);
      cache.set(key, { value, expiresAt });
    },

    /**
     * Retrieves a value only if it has not expired relative to nowMs.
     */
    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (!entry) {
        return undefined;
      }

      // Check for expiration
      if (nowMs >= entry.expiresAt) {
        // Entry is expired, optionally clean it up here if desired, but definitionally 'get' just returns the value/undefined based on status.
        cache.delete(key); 
        return undefined;
      }

      return entry.value;
    },

    /**
     * Checks for existence and liveness of a key at nowMs.
     */
    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      if (!entry) {
        return false;
      }

      // Check for expiration
      return nowMs < entry.expiresAt && entry.value !== undefined; // Note: checking against undefined here is incorrect for the requirement "Store undefined is valid". We must rely solely on time check.
      // Corrected logic based on requirements: has(...) must report presence correctly for live entries, even if value was undefined.
      return nowMs < entry.expiresAt && cache.has(key); 
    },

    /**
     * Deletes an entry by key and returns true if the entry existed and was removed, false otherwise.
     */
    delete(key: string): boolean {
        if (cache.has(key)) {
            // We don't necessarily care about expiration checking before deletion, just if it exists.
            const exisisted = cache.get(key);
            if (exisisted) {
                 cache.delete(key);
                 return true;
            }
        }
        return false;
    },

    /**
     * Counts the number of currently live (non-expired) entries at the given timestamp.
     */
    size(nowMs: number): number {
      let count = 0;
      for (const entry of cache.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    /**
     * Removes all entries from the cache.
     */
    clear(): void {
      cache.clear();
    }
  };
}

/**
 * Defines the core interface and behavior contract for a TTL Cache utility.
 * @interface TtlCache The public interface exposed by createTtlCache().
 */
export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

/**
 * Creates and returns a fully functional in-memory TTL Cache object.
 * The cache uses a default Time To Live (TTL) of 1000ms if none is specified on set.
 * @returns {TtlCache} An object implementing the TtlCache interface.
 */
export function createTtlCache(): TtlCache {
  // Using private symbol to enforce internal state protection and prevent external modification
  // Key: string, Value: CacheEntry (value and expiration time)
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  // Fixed default TTL as per requirements
  const DEFAULT_TTL_MS = 1000;

  /**
   * Checks if an entry is non-expired at the given current time.
   * @param nowMs The current timestamp in milliseconds.
   * @param entry The cache entry object.
   * @returns {boolean} True if the entry has not expired, false otherwise.
   */
  const isExpired = (nowMs: number, entry: { expiresAt: number }): boolean => {
    return nowMs >= entry.expiresAt;
  };

  /**
   * Defines a new value in the cache or refreshes an existing one.
   * @param key The unique key for the entry.
   * @param value The value to store (can be undefined).
   * @param nowMs The current timestamp used as calculation base.
   * @param ttlMs Optional custom TTL in milliseconds. If 0, expires immediately.
   */
  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    let expiresAt: number;

    // Handle explicit immediate expiration (ttlMs = 0)
    if (typeof ttlMs === 'number' && ttlMs <= 1) {
        expiresAt = nowMs; // Expires at the moment of setting/use
    } else if (typeof ttlMs === 'number' && ttlMs > 0) {
      // Use provided TTL
      expiresAt = nowMs + ttlMs;
    } else {
      // Use default TTL (1000ms)
      expiresAt = nowMs + DEFAULT_TTL_MS;
    }

    cache.set(key, { value: value, expiresAt: expiresAt });
  };

  /**
   * Retrieves a value if it exists and has not expired at `nowMs`.
   * @param key The key to retrieve.
   * @param nowMs The current timestamp used for expiration check.
   * @returns {unknown | undefined} The stored value, or undefined if non-existent or expired.
   */
  const get = (key: string, nowMs: number): unknown => {
    const entry = cache.get(key);

    if (!entry || isExpired(nowMs, entry)) {
      // If expired, delete it to keep the map clean
      cache.delete(key);
      return undefined;
    }
    return entry.value;
  };

  /**
   * Checks if a key exists and has not expired at `nowMs`.
   * @param key The key to check.
   * @param nowMs The current timestamp used for expiration check.
   * @returns {boolean} True if the entry is present and valid, false otherwise.
   */
  const has = (key: string, nowMs: number): boolean => {
    const entry = cache.get(key);

    if (!entry || isExpired(nowMs, entry)) {
      // Clean up upon check failure to maintain a sparse map of only valid items
      cache.delete(key);
      return false;
    }
    return true;
  };

  /**
   * Explicitly removes an entry from the cache.
   * @param key The key to delete.
   * @returns {boolean} True if the key was found and removed, false otherwise.
   */
  const deleteCacheEntry = (key: string): boolean => {
    if (!cache.has(key)) {
      return false;
    }
    cache.delete(key);
    return true;
  };

  /**
   * Counts the number of entries that have not expired at `nowMs`.
   * Note: This should also perform cleanup checks for accuracy.
   * @param nowMs The current timestamp used for counting non-expired items.
   * @returns {number} The count of valid, non-expired entries.
   */
  const size = (nowMs: number): number => {
    let count = 0;

    // Iterate over keys and clean up expired ones while counting
    for (const [key, entry] of cache.entries()) {
      if (isExpired(nowMs, entry)) {
        cache.delete(key);
      } else {
        count++;
      }
    }

    return count;
  };

  /**
   * Clears all entries from the cache storage.
   */
  const clear = (): void => {
    cache.clear();
  };


  // Return an object that conforms exactly to the TtlCache interface
  return {
    set,
    get,
    has,
    delete: deleteCacheEntry,
    size,
    clear
  } as TtlCache;

}

