type RateLimitState = {
    windowStartMs: number;
    requestCount: number;
};

// Internal store to hold rate limit state for all keys
const quotas = new Map<string, RateLimitState>();
const MAX_REQUESTS = 3;
const WINDOW_MS = 1000;

/**
 * Factory function that creates a rate limiting object enforcing fixed time windows.
 * @returns {object} An API containing allow, remaining, and reset methods.
 */
export function createRateLimiter() {
    return {
        /**
         * Checks if a request for the given key is allowed at nowMs.
         * It also updates the internal rate limit state.
         */
        allow: (key: string, nowMs: number): boolean => {
            let quota = quotas.get(key);

            // 1. Initialize or refresh window if necessary
            if (!quota) {
                quota = { windowStartMs: nowMs, requestCount: 0 };
                quotas.set(key, quota);
            } else {
                const elapsed = nowMs - quota.windowStartMs;

                // Boundary Rule Check: If the window has fully elapsed, reset state to start new window now.
                if (elapsed >= WINDOW_MS) {
                    quota.windowStartMs = nowMs;
                    quota.requestCount = 0;
                    quotas.set(key, quota);
                } else {
                    // Window is active. No action needed on state initialization / reset.
                }
            }

            // 2. Check limit enforcement
            const remaining = this.remaining(key, nowMs);

            if (remaining > 0) {
                // Consume request
                quota.requestCount += 1;
                quotas.set(key, quota);
                return true;
            } else {
                // Throttled
                return false;
            }
        },

        /**
         * Calculates the number of remaining requests for the key at nowMs.
         * This method ensures the internal state is synchronized with the time provided.
         */
        remaining: (key: string, nowMs: number): number => {
            let quota = quotas.get(key);

            // 1. Initialization and Window Boundary Check
            if (!quota) {
                // Initialize: Start window now, 0 requests used.
                quota = { windowStartMs: nowMs, requestCount: 0 };
                quotas.set(key, quota);
            } else {
                const elapsed = nowMs - quota.windowStartMs;

                // Boundary Rule Check: If the window has fully elapsed, reset state to start new window now.
                if (elapsed >= WINDOW_MS) {
                    quota.windowStartMs = nowMs; // Start new window
                    quota.requestCount = 0;
                    quotas.set(key, quota);
                }
            }

            // Since we checked boundary conditions and updated the state if needed,
            // the remaining count is simply calculated from the current state.
            const remaining = Math.max(0, MAX_REQUESTS - quota.requestCount);

            return remaining;
        },

        /**
         * Clears only that key's rate limit state.
         */
        reset: (key: string): void => {
            quotas.delete(key);
        }
    };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  // Maps key to its state: { count (current usage), windowStartMs (start time of current window) }
  const store = new Map<string, { count: number; windowStartMs: number }>();

  const LIMIT = 3;
  const WINDOW_MS = 1000;

  /**
   * Gets or initializes the state for a given key. Handles boundary reset logic automatically.
   */
  const getState = (key: string, nowMs: number): { count: number; windowStartMs: number } => {
    const currentState = store.get(key);

    if (!currentState || nowMs - currentState.windowStartMs >= WINDOW_MS) {
      // Window expired or key does not exist, reset state
      store.set(key, { count: 1, windowStartMs: nowMs });
      return store.get(key)!;
    } else if (currentState && nowMs - currentState.windowStartMs < WINDOW_MS) {
      // Key exists and window is still valid
      return currentState;
    }
    // Fallback case (should not happen): reset to current time/count
    store.set(key, { count: 1, windowStartMs: nowMs });
    return store.get(key)!;
  };


  /**
   * Determines if the key is allowed access at the given time.
   */
  const allow = (key: string, nowMs: number): boolean => {
    if (store.has(key)) {
      // Check boundary reset upon calling allow
      let state = getState(key, nowMs);

      if (state.count < LIMIT) {
        state.count += 1;
        return true;
      } else {
        // Limit reached in current window
        return false;
      }
    } else {
      // New key, initialize and allow access
      store.set(key, { count: 1, windowStartMs: nowMs });
      return true;
    }
  };

  /**
   * Returns the remaining quota for the key at the given time.
   */
  const remaining = (key: string, nowMs: number): number => {
    let state = store.get(key);

    if (!state || nowMs - state.windowStartMs >= WINDOW_MS) {
      // Window expired or key does not exist, reset window and report full quota minus 1 (since current attempt hasn't counted)
      store.set(key, { count: 0, windowStartMs: nowMs }); // Initialize count to 0 for accurate remaining calculation
      return LIMIT;
    }

    // Window is active, calculate remaining
    const currentCount = state.count;
    return Math.max(0, LIMIT - currentCount);
  };

  /**
   * Removes the key's state from the rate limiter store.
   */
  const reset = (key: string): void => {
    store.delete(key);
  };

  // Return an object implementing the RateLimiter interface
  return {
    allow,
    remaining,
    reset,
  } as RateLimiter;
}

