type Todo = {
    id: number;
    text: string;
    completed: boolean;
};

/**
 * Factory function that creates and returns an interface for managing a todo list.
 */
export function createTodoApp(): {
    addTodo(text: string): Todo;
    getTodo(id: number): Todo | undefined;
    toggleTodo(id: number): void;
    deleteTodo(id: number): boolean;
    listTodos(): ReadonlyArray<Todo>;
    listCompleted(): ReadonlyArray<Todo>;
    listPending(): ReadonlyArray<Todo>;
    clearCompleted(): void;
} {
    const todos: Todo[] = [];
    let nextId: number = 1;

    return {
        addTodo(text: string): Todo => {
            if (typeof text !== 'string' || text.trim().length === 0) {
                throw new Error("Todo text cannot be empty.");
            }
            const newTodo: Todo = {
                id: nextId++,
                text: text,
                completed: false,
            };
            todos.push(newTodo);
            return { ...newTodo }; // Return a copy as required by contract
        },

        getTodo(id: number): Todo | undefined => {
            const todo = todos.find(t => t.id === id);
            return todo || undefined;
        },

        toggleTodo(id: number): void => {
            const todoIndex = todos.findIndex(t => t.id === id);
            if (todoIndex !== -1) {
                // Create a copy to ensure immutability principle if this were an external state update,
                // but since we are modifying the internal list state, we just change it directly.
                todos[todoIndex] = { ...todos[todoIndex], completed: !todos[todoIndex].completed };
            }
        },

        deleteTodo(id: number): boolean => {
            const initialLength = todos.length;
            // Filter out the todo with the specified id
            for (let i = todos.length - 1; i >= 0; i--) {
                if (todos[i].id === id) {
                    // Remove it and return true immediately
                    const deleted = todos.splice(i, 1)[0];
                    return !!deleted;
                }
            }
            return false;
        },

        listTodos: (): ReadonlyArray<Todo> => {
            // Return a shallow copy made readonly to prevent external mutation of the internal state
            return [...todos] as ReadonlyArray<Todo>;
        },

        listCompleted: (): ReadonlyArray<Todo> => {
            const completed = todos.filter(t => t.completed);
            return [...completed] as ReadonlyArray<Todo>;
        },

        listPending: (): ReadonlyArray<Todo> => {
            const pending = todos.filter(t => !t.completed);
            return [...pending] as ReadonlyArray<Todo>;
        },

        clearCompleted: () => {
            // Filter the state, keeping only non-completed items
            todos.length = 0; // Clear array first might be risky if we rely on indexes/IDs
            const pendingTodos = todos.filter(t => !t.completed);

            // Rebuild the internal todos array with only active entries (maintaining original IDs)
    		// Note: We must ensure that 'nextId' is not incremented here, and existing IDs remain valid.
    		// Since we are just filtering/keeping items, simply reassigning the contents is fine.
            const filteredTodos: Todo[] = [];
            let currentIdMap = new Map<number, Todo>();

            for (const todo of todos) {
                if (!todo.completed) {
                    filteredTodos.push(todo);
                    currentIdMap.set(todo.id, todo);
                }
            }

            todos.splice(0, todos.length, ...filteredTodos);

            // To meet the constraint that IDs are never reused, and assuming 'clearCompleted' simply empties
            // completed items without invalidating active ones: reassigning handles this correctly.
        }
    };
}

export function createTodoApp(): TodoApp {
  const todos: Todo[] = [];
  let nextId = 1;

  /**
   * @typedef Interface { id: number, text: string, completed: boolean }
   */
  /**
   * @typedef Interface {
   *   addTodo(text: string): Todo
   *   getTodo(id: number): Todo | undefined
   *   toggleTodo(id: number): void
   *   deleteTodo(id: number): boolean
   *   listTodos(): Todo[]
   *   listCompleted(): Todo[]
   *   listPending(): Todo[]
   *   clearCompleted(): void
   * }
   */

  /**
   * Adds a new todo item.
   * @param {string} text The text content of the todo.
   * @returns {Todo} The created Todo object.
   */
  const addTodo = (text: string): Todo => {
    const nuevoTodo: Todo = {
      id: nextId++,
      text,
      completed: false
    };
    todos.push(nuevoTodo);
    return nuevoTodo;
  };

  /**
   * Gets a todo by its ID.
   * @param {number} id The ID of the todo to retrieve.
   * @returns {Todo | undefined} The Todo object or undefined if not found.
   */
  const getTodo = (id: number): Todo | undefined => {
    return todos.find(todo => todo.id === id);
  };

  /**
   * Toggles the completion status of a todo item. Does nothing if ID is missing/invalid.
   * @param {number} id The ID of the todo to toggle.
   */
  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) {
      // To ensure we modify the stored object, find the reference and change it.
      const index = todos.findIndex(t => t.id === id);
      if (index !== -1) {
        todos[index].completed = !todos[index].completed;
      }
    }
  };

  /**
   * Deletes a todo by ID.
   * @param {number} id The ID of the todo to delete.
   * @returns {boolean} True if the todo was deleted, false otherwise.
   */
  const deleteTodo = (id: number): boolean => {
    const initialLength = todos.length;
    // Filter out the todo with the matching ID
    for (let i = 0; i < todos.length; i++) {
        if (todos[i].id === id) {
            // Use splice for removal if performance is key, but setting length often works fine too.
             todos.splice(i, 1);
             return true;
        }
    }
    return false;
  };

  /**
   * Retrieves all todos.
   * @returns {Todo[]} An array containing all stored Todo objects.
   */
  const listTodos = (): Todo[] => {
    // Return a defensive copy of the current state
    return [...todos];
  };

  /**
   * Retrieves all completed todos.
   * @returns {Todo[]} An array containing only completed Todo objects.
   */
  const listCompleted = (): Todo[] => {
    return todos.filter(todo => todo.completed);
  };

  /**
   * Retrieves all pending todos.
   * @returns {Todo[]} An array containing only pending (uncompleted) Todo objects.
   */
  const listPending = (): Todo[] => {
    return todos.filter(todo => !todo.completed);
  };

  /**
   * Removes all completed todos from the list entirely.
   */
  const clearCompleted = (): void => {
    // Recalculate state by keeping only non-completed items
    for (let i = todos.length - 1; i >= 0; i--) {
        if (todos[i].completed) {
            todos.splice(i, 1);
        }
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}

