export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    /**
     * Sets a key-value pair in the cache and refreshes its expiration time.
     */
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const defaultTtl = 1000;
      const effectiveTtl = ttlMs === undefined ? defaultTtl : ttlMs;
      const expiresAt = nowMs + effectiveTtl;

      // Note: We store the actual expiration time.
      cache.set(key, { value, expiresAt });
    },

    /**
     * Retrieves a value only if it has not expired at the given timestamp.
     */
    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);

      if (!entry) {
        return undefined; // Missing key
      }

      if (nowMs >= entry.expiresAt) {
        // Expired entry, clean it up and treat as not found
        this['delete'](key); 
        return undefined;
      }

      return entry.value;
    },

    /**
     * Checks if a key exists and is currently live at the given timestamp.
     */
    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);

      if (!entry) {
        return false; // Missing key
      }

      return nowMs < entry.expiresAt; // Live if current time is before expiration
    },

    /**
     * Deletes a key from the cache, returns true if it existed and was removed.
     */
    delete(key: string): boolean {
      if (cache.has(key)) {
        cache.delete(key);
        return true;
      }
      return false;
    },

    /**
     * Counts the number of non-expired entries at the given timestamp.
     */
    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of cache.entries()) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
            // Optimization: If we hit an expired key during size calculation, 
            // we should probably clear it to keep the map clean, 
            // although not strictly required by API spec on failure/success.
            // To fulfill 'size' requirement robustly, let's just count and rely on repeated calls/ops to clean up.
        }
      }
      return count;
    },

    /**
     * Clears all entries from the cache.
     */
    clear(): void {
      cache.clear();
    }
  };
}

type CacheEntry = {
    value: unknown;
    expiresAt: number;
};

/**
 * Creates a Time-To-Live cache instance.
 */
export function createTtlCache(): TtlCache {
    // Use Map to store key -> { value, expiresAt }
    const storage = new Map<string, CacheEntry>();

    // Fixed default TTL: 1000ms
    const DEFAULT_TTL_MS = 1000;

    /**
     * Checks if a cache entry is expired relative to nowMs.
     * @param key The key to check.
     * @param nowMs Current timestamp in milliseconds.
     * @returns True if expired or deleted, false otherwise.
     */
    const isExpired = (key: string, nowMs: number): boolean => {
        const entry = storage.get(key);
        if (!entry) return true; // Key doesn't exist
        return nowMs >= entry.expiresAt;
    };

    /**
     * Sets a value with optional TTL (defaults to 1000ms).
     */
    const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
        let expiresAt = nowMs + DEFAULT_TTL_MS;

        if (typeof ttlMs === 'number') {
            if (ttlMs <= 0) {
                // Handle immediate expiration or custom zero TTL
                expiresAt = nowMs > 0 ? nowMs : Number.MIN_SAFE_INTEGER; // Set to a time before current if possible, effectively expired immediately upon checking/accessing unless nowMs is used directly in check. Let's set it slightly ahead of the calculation point based on `nowMs` if needed, but for ttl=0, we want immediate expiration after setting.
                // Setting expiresAt = nowMs ensures that any subsequent read at or after nowMs fails expiration check.
               expiresAt = nowMs; 
            } else {
                expiresAt = nowMs + ttlMs;
            }
        }

        storage.set(key, { value, expiresAt });
    };

    /**
     * Gets a value for the given key if it has not expired.
     */
    const get = (key: string, nowMs: number): unknown | undefined => {
        if (isExpired(key, nowMs)) {
            // Clean up expired entry immediately upon access attempt
            deleteStorageKey(key);
            return undefined;
        }

        const entry = storage.get(key)!;
        return entry.value;
    };

    /**
     * Checks if the key exists and is not expired.
     */
    const has = (key: string, nowMs: number): boolean => {
        // Check existence AND non-expiration
        if (!storage.has(key)) return false;
        return !isExpired(key, nowMs);
    };

    /**
     * Removes an entry and returns true if it was present/removed, otherwise false.
     */
    const deleteEntry = (key: string): boolean => {
        if (!storage.has(key)) return false;
        deleteStorageKey(key);
        return true;
    };

    /* Helper function to handle deletion across methods */
    const deleteStorageKey = (key: string) => {
        // We only need to remove the entry from the map regardless of expiration status for 'delete' semantics.
        storage.delete(key);
    }


    /**
     * Counts non-expired entries at a given point in time.
     */
    const size = (nowMs: number): number => {
        let count = 0;
        for (const [key, entry] of storage.entries()) {
            if (!isExpired(key, nowMs)) {
                count++;
            }
        }
        return count;
    };

    /**
     * Removes all entries from the cache and returns void.
     */
    const clearCache = (): void => {
        storage.clear();
    };


    // Return the TtlCache implementation object
    return {
        set: (key, value, nowMs, ttlMs) => set(key, value, nowMs, ttlMs),
        get: (key, nowMs) => get(key, nowMs),
        has: (key, nowMs) => has(key, nowMs),
        delete: (key) => deleteEntry(key),
        size: (nowMs) => size(nowMs),
        clear: () => clearCache(),
    };
}

