export function createCalculator(): {
    add: (n: number) => API;
    subtract: (n: number) => API;
    multiply: (n: number) => API;
    divide: (n: number) => API;
    clear: () => API;
    result: () => number;
    memoryStore: (() => API);
    memoryAdd: (() => API);
    memoryClear: (() => API);
    memoryRecall: () => number;
} & { [key: string]: any } {
    let currentVal = 0;
    let memoryValue = 0;

    const api = {
        add: (n: number) => {
            currentVal += n;
            return api;
        },
        subtract: (n: number) => {
            currentVal -= n;
            return api;
        },
        multiply: (n: number) => {
            currentVal *= n;
            return api;
        },
        divide: (n: number) => {
            if (n === 0) throw new Error("Cannot divide by zero");
            currentVal /= n;
            return api;
        },
        clear: () => {
            currentVal = 0;
            return api;
        },
        result: (): number => currentVal,
        memoryStore: () => {
            memoryValue = currentVal;
            return api;
        },
        memoryAdd: () => {
            // Adds the *current* value to memory. Does NOT change current value.
            memoryValue += currentVal;
            return api;
        },
        memoryClear: () => {
            memoryValue = 0;
            return api;
        },
        memoryRecall: (): number => {
            // Returns the stored memory value and does NOT change current value.
            return memoryValue;
        }
    };

    return api as any;
}

type Calculator = {
    add: (n: number) => Calculator;
    subtract: (n: number) => Calculator;
    multiply: (n: number) => Calculator;
    divide: (n: number) => Calculator;
    clear: () => Calculator;
    result: () => number;
    memoryStore: () => Calculator;
    memoryRecall: () => number;
    memoryClear: () => Calculator;
    memoryAdd: () => Calculator;
};

export function createCalculator(): Calculator {
    let currentValue = 0;
    let memory = 0;

    const calculatorInstance: Calculator = {
        add: (n: number): Calculator => {
            currentValue += n;
            return calculatorInstance;
        },
        subtract: (n: number): Calculator => {
            currentValue -= n;
            return calculatorInstance;
        },
        multiply: (n: number): Calculator => {
            currentValue *= n;
            return calculatorInstance;
        },
        divide: (n: number): Calculator => {
            if (n === 0) throw new Error("Division by zero is not allowed.");
            currentValue /= n;
            return calculatorInstance;
        },
        clear: (): Calculator => {
            currentValue = 0;
            return calculatorInstance;
        },
        result: (): number => {
            return currentValue;
        },
        memoryStore: (): Calculator => {
            // Store current value in memory
            memory = currentValue;
            return calculatorInstance;
        },
        memoryRecall: (): number => {
            return memory;
        },
        memoryClear: (): Calculator => {
            // Memory remains the same, just return the object to keep chaining.
            return calculatorInstance;
        },
        memoryAdd: (): Calculator => {
            // Adds current value into memory without changing currentValue
            // Note: Original behavior interpretation leads to accumulator pattern for memory add.
            // Assuming it meant 'accumulate previous memory + currentValue' 
            // If the requirement was strictly "add current value INTO memory", it means memory = memory + currentValue.
            memory += currentValue;
            return calculatorInstance;
        }
    };

    return calculatorInstance;
}

type Emitter = {
    on: (event: string, listener: (...args: any[]) => void) => number;
    once: (event: string, listener: (...args: any[]) => void) => number;
    off: (event: string, listener: (...args: any[]) => void): boolean;
    emit: (event: string, payload?: any[]): Array<any>;
    listenerCount: (event: string) => number;
};

export function createEventEmitter(): Emitter {
    // Stores normal listeners and one-time listeners for each event name.
    const internalListeners = new Map<string, { 
        normal: Function[]; // Functions are used by reference to track identity
        once: Function[] 
    }>();

    // Helper function to safely retrieve or initialize an event's listener state.
    const getEventData = (eventName: string) => {
        if (!internalListeners.has(eventName)) {
            internalListeners.set(eventName, { normal: [], once: [] });
        }
        return internalListeners.get(eventName)!;
    };

    // Registers a permanent listener. Returns the new total count of listeners for this event.
    const on = (event: string, listener: (...args: any[]) => void): number => {
        const data = getEventData(event);
        data.normal.push(listener);
        return data.normal.length + data.once.length;
    };

    // Registers a temporary, single-use listener. Returns the new total count of listeners for this event.
    const once = (event: string, listener: (...args: any[]) => void): number => {
        const data = getEventData(event);
        data.once.push(listener);
        return data.normal.length + data.once.length;
    };

    // Removes one matching listener from either normal or once lists. Returns true if removed, false otherwise.
    const off = (event: string, listener: (...args: any[]) => void): boolean => {
        if (!internalListeners.has(event)) return false;

        const data = internalListeners.get(event)!;

        // Attempt removal from normal listeners first
        const indexNormal = data.normal.findIndex(l => l === listener);
        if (indexNormal !== -1) {
            data.normal.splice(indexNormal, 1);
            return true;
        }

        // Then attempt removal from once listeners
        const indexOnce = data.once.findIndex(l => l === listener);
        if (indexOnce !== -1) {
            data.once.splice(indexOnce, 1);
            return true;
        }

        return false;
    };

    // Fires all registered listeners for the event in order. Removes 'once' listeners after execution.
    // Returns an array containing the return values of every executed listener.
    const emit = (event: string, payload?: any[]): Array<any> => {
        if (!internalListeners.has(event)) {
            return [];
        }

        const data = internalListeners.get(event)!;
        const results: any[] = []; 
        const onceExecutedIndices: number[] = [];

        // Execute normal listeners (non-destructive)
        for (const listener of data.normal) {
            try {
                const result = listener(payload);
                results.push(result);
            } catch (e) {
                // Per standard EventEmitter behavior, internal errors are often caught and ignored 
                // to allow subsequent listeners to fire. We still record the failure if possible.
                console.error("Error in normal listener:", e);
            }
        }

        // Execute once listeners and track indices for removal
        for (let i = 0; i < data.once.length; i++) {
            const listener = data.once[i];
            try {
                const result = listener(payload);
                results.push(result);
                onceExecutedIndices.push(i); // Store index for removal
            } catch (e) {
                 console.error("Error in once listener:", e);
            }
        }

        // Remove executed 'once' listeners by traversing indices in reverse order
        onceExecutedIndices.sort((a, b) => b - a).forEach(index => {
            data.once.splice(index, 1);
        });

        return results;
    };

    // Returns the total number of registered listeners for an event.
    const listenerCount = (event: string): number => {
        if (!internalListeners.has(event)) {
            return 0;
        }
        const data = internalListeners.get(event)!;
        return data.normal.length + data.once.length;
    };

    return {
        on: on,
        once: once,
        off: off,
        emit: emit,
        listenerCount: listenerCount
    };
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  // Map<string, { listeners: Array<{ callback: Listener; isOnce: boolean; id: number}>, count: number }>
  const events = new Map<string, { listeners: any[]; count: number }>();
  let listenerIdCounter = 0;

  /**
   * Gets or creates the event storage object for a given event name.
   */
  const getEventStorage = (event: string) => {
    if (!events.has(event)) {
      events.set(event, { listeners: [], count: 0 });
    }
    return events.get(event)!;
  };

  /**
   * @param event The name of the event.
   * @param isOnce Whether this listener should be removed after one use.
   */
  const addListener = (event: string, listener: Listener, isOnce: boolean) => {
    const storage = getEventStorage(event);
    const id = ++listenerIdCounter;

    storage.listeners.push({ callback: listener, isOnce: isOnce, id: id });
    storage.count++;
    return storage.count; // Return current count as per spec (this means initial append)
  };

  /**
   * Searches for and removes exactly one matching listener registration by the provided function object.
   */
  const removeListener = (event: string, listener: Listener): boolean => {
    const storage = events.get(event);
    if (!storage) return false;

    for (let i = 0; i < storage.listeners.length; i++) {
      const entry = storage.listeners[i];
      // Using the raw function object comparison
      if (entry.callback === listener) {
        storage.listeners.splice(i, 1);
        storage.count--;
        return true;
      }
    }
    return false;
  };

  // --- Implementation of EventEmitter methods ---

  const on = (event: string, listener: Listener): number => {
    return addListener(event, listener, false);
  };

  const once = (event: string, listener: Listener): number => {
    return addListener(event, listener, true);
  };

  const off = (event: string, listener: Listener): boolean => {
    return removeListener(event, listener);
  };

  const emit = (event: string, payload: unknown): Promise<unknown[]> => {
    const storage = events.get(event);
    if (!storage || storage.listeners.length === 0) {
      return Promise.resolve([]);
    }

    // Clone the listeners array to safely handle removals during iteration (especially for 'once')
    let currentListeners: any[] = [...storage.listeners];
    const results: unknown[] = [];

    /**
     * Executes a single listener and handles cleanup if necessary.
     */
    const executeListener = (entry: { callback: Listener; isOnce: boolean; id: number }) => {
        try {
            // Assuming the return value of the listener function is what we capture.
            const result = entry.callback(payload);
            results.push(result);

            if (entry.isOnce) {
                // Mark this listener up for removal since it was invoked once.
                // We must remove all associated 'once' listeners in the main storage array at the end of emit, 
                // or more simply, clear them from the current list being processed if we know they are one-time only.
                // Since `once` is meant to be ephemeral: decrement count and remove entry explicitly after processing the entire list.
            }
        } catch (e) {
            // Handle potential errors in listener execution but continue emitting
            console.error(`Error executing listener for event "${event}":`, e);
        }
    };

    // Process all currently active listeners and collect results
    for (let i = 0; i < currentListeners.length; i++) {
      executeListener(currentListeners[i]);
    }

    /**
     * Cleanup phase for 'once' listeners after emit has finished collecting results.
     */
    const cleanupOnceListeners = () => {
        // Re-iterate over the full storage list to manage actual removals/counts
        const storage = events.get(event)!;
        for (let i = storage.listeners.length - 1; i >= 0; i--) {
            const entry = storage.listeners[i];
            if (entry.isOnce) {
                storage.listeners.splice(i, 1);
                storage.count--;
            }
        }
    };


    // The original spec dictates emit returns unknown[], suggesting sync execution and immediate return array.
    // Even though modern JS tends to use promises for event emitters, sticking strictly to the synchronous signature implied by `unknown[]`.

    const finalResults: unknown[] = [];
     for (let i = 0; i < currentListeners.length; i++) {
      executeListener(currentListeners[i]);
      finalResults.push(...results); // Overwrite results array usage for simplicity matching the return signature expectation
    }

    // Must execute cleanup *after* all listeners have been invoked.
    cleanupOnceListeners();

    return finalResults;
  };


  const listenerCount = (event: string): number => {
    const storage = events.get(event);
    return storage ? storage.count : 0;
  };

  // Exposing the structure matching the interface description
  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  } as EventEmitter;
}

type RateLimitState = { count: number; windowStartMs: number };
const keyStates = new Map<string, RateLimitState>();

/**
 * Creates a rate limiter factory that enforces per-key limits over fixed time windows.
 */
export const createRateLimiter = (): {
    allow: (key: string, nowMs: number) => boolean;
    remaining: (key: string, nowMs: number) => number;
    reset: (key: string) => void;
} => {
    const CAPACITY = 3;
    const WINDOW_MS = 1000;

    /**
     * Helper to determine or reset the state for a key based on the current time.
     * @returns The mutable rate limit state object for modification within 'allow'.
     */
    const ensureWindowState = (key: string, nowMs: number): RateLimitState => {
        // Calculate the fixed start of the window that 'nowMs' belongs to (e.g., 0, 1000, 2000...)
        const targetWindowStartMs = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;

        let state = keyStates.get(key);

        // Check if the current window has changed or the key is new/undefined state means reset.
        if (!state || state.windowStartMs !== targetWindowStartMs) {
            state = { count: 0, windowStartMs: targetWindowStartMs };
        }
        return state;
    };

    const allow = (key: string, nowMs: number): boolean => {
        // Force the key state to synchronize with the fixed time window boundary of 'nowMs'.
        let currentState = ensureWindowState(key, nowMs);

        if (currentState.count < CAPACITY) {
            // Increment count and save updated state back to map.
            keyStates.set(key, {
                count: currentState.count + 1,
                windowStartMs: currentState.windowStartMs
            });
            return true;
        } else {
            return false;
        }
    };

    const remaining = (key: string, nowMs: number): number => {
        // Determine the fixed window boundary for 'nowMs'.
        const targetWindowStartMs = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;
        let state = keyStates.get(key);

        if (!state || state.windowStartMs !== targetWindowStartMs) {
            // If the window has crossed or key is unknown, reset state for calculation.
            keyStates.set(key, { count: 0, windowStartMs: targetWindowStartMs });
            state = keyStates.get(key)!;
        }

        return Math.max(0, CAPACITY - state.count);
    };

    const reset = (key: string): void => {
        // Simply delete the state associated with this key.
        keyStates.delete(key);
    };


    return {
        allow,
        remaining,
        reset
    };
};

type RateLimiterState = {
    count: number;
    windowStart: number;
};

// State storage for all keys. Using a Map<string, RateLimiterState>
const rateLimitStore = new Map<string, RateLimiterState>();

export function createRateLimiter(): RateLimiter {
    /**
     * Checks if the provided time window has expired for the given key, resetting the counter and start time if necessary.
     */
    const updateWindowStartAndCount = (key: string, nowMs: number): void => {
        let state = rateLimitStore.get(key);

        if (!state || nowMs - state.windowStart >= 1000) { // Check for window expiration
            // Window expired or key is new, reset the counter
            rateLimitStore.set(key, { count: 1, windowStart: nowMs });
        }
    };

    /**
     * Attempts to allow a request if the rate limit has not been exceeded in the current window.
     */
    const allow = (key: string, nowMs: number): boolean => {
        let state = rateLimitStore.get(key);

        if (!state || nowMs - state.windowStart >= 1000) {
            // Window expired or key is new, reset and set count to 1 because we are allowing this call
            rateLimitStore.set(key, { count: 1, windowStart: nowMs });
            return true;
        }

        if (state.count < 3) {
            // Within limit, increment count and allow
            const newState = { ...state, count: state.count + 1 };
            rateLimitStore.set(key, newState);
            return true;
        } else {
            // Limit reached
            return false;
        }
    };

    /**
     * Returns the remaining usage quota for the key in the current window.
     */
    const remaining = (key: string, nowMs: number): number => {
        let state = rateLimitStore.get(key);

        if (!state || nowMs - state.windowStart >= 1000) {
            // New window starts, always full
            rateLimitStore.set(key, { count: 1, windowStart: nowMs });
            return 3 - 1; // Remaining is 2, because the current call will consume one slot initially if used immediately afterwards, but generally we return remaining capacity relative to the limit.
        }

        // Current active window
        const spotsUsed = state.count;
        const availableSpots = 3 - spotsUsed;

        if (availableSpots < 0) {
             return 0; // Already over limit
        }
        return Math.max(0, 3 - spotsUsed);
    };

    /**
     * Removes the state for a specific key from the store.
     */
    const reset = (key: string): void => {
        rateLimitStore.delete(key);
    };


    return {
        allow,
        remaining,
        reset
    } as RateLimiter;
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

