export function createTodoApp() {
  const todos: Array<{ id: number, text: string, completed: boolean }> = [];
  let nextId: number = 1;

  /**
   * Helper function to generate unique IDs.
   * Since existing constraints suggest IDs can never be reused after deletion, we simply increment a counter for simplicity following typical patterns unless ID reuse tracking is explicitly required.
   */
  const getNextId = (): number => {
    const id = nextId++;
    return id;
  };

  /**
   * Adds a new todo item.
   * @param text The content of the todo.
   * @returns The full created todo object.
   */
  const addTodo = (text: string): { id: number, text: string, completed: boolean } => {
    const newTodo = { id: getNextId(), text, completed: false };
    todos.push(newTodo);
    return { ...newTodo };
  };

  /**
   * Finds a todo by ID.
   * @param id The ID of the todo to retrieve.
   * @returns The todo object or undefined if not found.
   */
  const getTodo = (id: number): { id: number, text: string, completed: boolean } | undefined => {
    return todos.find(todo => todo.id === id);
  };

  /**
   * Toggles the completion status of a todo by ID. Does nothing if ID is missing/invalid.
   * @param id The ID of the todo to toggle.
   */
  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) {
      // Find and update state immutably or directly if performance is critical for a small app. Direct mutation is fine for closure scope.
      const index = todos.findIndex(t => t.id === id);
      if (index !== -1) {
        todos[index].completed = !todos[index].completed;
      }
    }
  };

  /**
   * Deletes a todo by ID.
   * @param id The ID of the todo to delete.
   * @returns True if the todo was deleted, false otherwise.
   */
  const deleteTodo = (id: number): boolean => {
    const initialLength = todos.length;
    const index = todos.findIndex(t => t.id === id);

    if (index !== -1) {
      // To completely satisfy "IDs are never reused after deletion," 
      // ideally we should remove the ID from a set of available IDs, 
      // but since we are using a simple counter approach for simplicity:
      todos.splice(index, 1);
      return true;
    }
    return false;
  };

  /**
   * Lists all todos in creation order.
   * @returns Array of all todo objects.
   */
  const listTodos = (): Array<{ id: number, text: string, completed: boolean }> => {
    // Return a shallow copy to prevent external modification of state
    return [...todos];
  };

  /**
   * Lists only completed todos.
   * @returns Array of completed todo objects.
   */
  const listCompleted = (): Array<{ id: number, text: string, completed: boolean }> => {
    return todos.filter(t => t.completed);
  };

  /**
   * Lists all pending (incomplete) todos.
   * @returns Array of pending todo objects.
   */
  const listPending = (): Array<{ id: number, text: string, completed: boolean }> => {
    return todos.filter(t => !t.completed);
  };

  /**
   * Removes all completed todos from the internal state array.
   */
  const clearCompleted = (): void => {
    const initialLength = todos.length;
    // Filter to keep only incomplete todos in place
    const newTodos: Array<{ id: number, text: string, completed: boolean }> = [];
    let keptIds = new Set<number>();

    todos.forEach(todo => {
      if (!todo.completed) {
        newTodos.push(todo);
        keptIds.add(todo.id);
      }
    });

    // Reset the internal state reference
    // Note: If we strictly adhere to "IDs are never reused after deletion," 
    // simply splicing/filtering might create ID gaps that future additions overwrite if not careful, but for this scoped solution, array replacement suffices.
    // We ensure only non-completed items remain.
    Object.assign(todos, newTodos);
  };


  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}

export function createTodoApp(): TodoApp {
  const todos: Map<number, Todo> = new Map();
  let nextId = 1;

  /**
   * @typedef {{ id: number, text: string, completed: boolean }} Todo
   * @typedef {{ addTodo(text: string): Todo; getTodo(id: number): Todo | undefined; toggleTodo(id: number): void; deleteTodo(id: number): boolean; listTodos(): readonly Todo[]; listCompleted(): readonly Todo[]; listPending(): readonly Todo[]; clearCompleted(): void }} TodoApp
   */

  const todoApp = {
    /**
     * Adds a new to-do item.
     * @param text The text content of the todo.
     * @returns The created Todo object including its ID.
     */
    addTodo: (text: string): Todo => {
      const newId = nextId++;
      /** @type {Todo} */
      const newTodo = { id: newId, text, completed: false };
      todos.set(newId, newTodo);
      return newTodo;
    },

    /**
     * Retrieves a specific todo by ID.
     * @param id The ID of the todo.
     * @returns The Todo object or undefined if not found.
     */
    getTodo: (id: number): Todo | undefined => {
      return todos.get(id);
    },

    /**
     * Toggles the completion status of a todo item. Does nothing if ID is invalid.
     * @param id The ID of the todo to toggle.
     */
    toggleTodo: (id: number): void => {
      const todo = todos.get(id);
      if (todo) {
        todo.completed = !todo.completed;
        // Update the map entry explicitly if passing a mutable reference is not guaranteed, 
        // though in JS/TS objects are usually passed by reference for mutation purposes.
        todos.set(id, todo);
      }
    },

    /**
     * Deletes a to-do item by ID. Returns true if deleted, false otherwise.
     * @param id The ID of the todo to delete.
     * @returns True if the todo was found and deleted, false otherwise.
     */
    deleteTodo: (id: number): boolean => {
      if (todos.has(id)) {
        todos.delete(id);
        return true;
      }
      return false;
    },

    /**
     * Returns an array of all existing to-do items.
     */
    listTodos: (): readonly Todo[] => {
      return Array.from(todos.values());
    },

    /**
     * Returns an array of completed to-do items.
     */
    listCompleted: (): readonly Todo[] => {
      const completed = [];
      for (const todo of todos.values()) {
        if (todo.completed) {
          completed.push(todo);
        }
      }
      return completed;
    },

    /**
     * Returns an array of pending to-do items.
     */
    listPending: (): readonly Todo[] => {
      const pending = [];
      for (const todo of todos.values()) {
        if (!todo.completed) {
          pending.push(todo);
        }
      }
      return pending;
    },

    /**
     * Removes all completed to-do items from the list.
     */
    clearCompleted: (): void => {
      for (const todo of todos.values()) {
        if (todo.completed) {
          todos.delete(todo.id);
        }
      }
    }
  };

  return todoApp;
}

