export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs) {
      let toLiveUntil = nowMs + (ttlMs ?? 1000);
      cache.set(key, { value, expiresAt: toLiveUntil });
    },

    get(key, nowMs) {
      const entry = cache.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      // Note: Returning undefined is fine if the value stored was indeed 'undefined'.
      // The check handles expiration first, which is sufficient for correctness.
      return entry.value;
    },

    has(key, nowMs) {
      const isExpired = cache.has(key) && (nowMs >= (cache.get(key)?.expiresAt ?? 0));
      // We report true if the key exists AND it hasn't expired based on nowMs.
      return !isExpired;
    },

    delete(key) {
      const existed = cache.has(key);
      if (existed) {
        cache.delete(key);
        return true;
      }
      return false;
    },

    size(nowMs) {
      let count = 0;
      for (const entry of cache.values()) {
        // Only count entries that haven't expired at nowMs
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear() {
      cache.clear();
    }
  };
}

interface CacheEntry {
  value: unknown;
  expiresAt: number;
}

const DEFAULT_TTL = 1000; // Fixed default TTL in ms

export function createTtlCache(): TtlCache {
  /** @type {Map<string, CacheEntry>} */
  const cache = new Map();

  const checkExpiration = (entry: CacheEntry, nowMs: number): boolean => {
    return entry.expiresAt < nowMs;
  };

  /**
   * Checks if the key exists and is not expired relative to nowMs.
   */
  const isEntryValid = (key: string, nowMs: number): boolean => {
    if (!cache.has(key)) {
      return false;
    }
    const entry = cache.get(key)!;
    return !checkExpiration(entry, nowMs);
  };

  /**
   * Sets a value in the cache, overwriting if exists, and refreshing expiration.
   * @param key The cache key.
   * @param value The value to store (can be undefined).
   * @param nowMs Current timestamp in milliseconds.
   * @param ttlMs Optional time-to-live in milliseconds. Uses fixed default TTL if 0 or skipped.
   */
  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    let expiresAt: number;

    // 1. Handle immediate expiration override
    if ((ttlMs === undefined || ttlMs > 0) && ttlMs !== null) {
      expiresAt = ttlMs === 0 ? nowMs : nowMs + (ttlMs ?? DEFAULT_TTL);
    } else {
      // Use fixed default TTL if ttlMs is explicitly passed as 0, or undefined/null and not handled above.
      // The requirements state: If ttlMs=0 means immediate expiration (handled by the check below)
      // Fixed default TTL: 1000ms
      expiresAt = nowMs + DEFAULT_TTL;
    }

    // Special handling for explicit setting of ttlMs = 0, enforcing immediate expiry.
    if (ttlMs === 0) {
        expiresAt = nowMs;
    }


    const entry: CacheEntry = {
      value: value,
      expiresAt: expiresAt,
    };
    cache.set(key, entry);
  };

  /**
   * Retrieves a value from the cache if it exists and has not expired.
   * @param key The cache key.
   * @param nowMs Current timestamp in milliseconds.
   * @returns The cached value or undefined if expired/not found.
   */
  const get = (key: string, nowMs: number): unknown => {
    if (!isEntryValid(key, nowMs)) {
      return undefined; // Must return undefined when reading an expired key
    }
    return cache.get(key)!.value;
  };

  /**
   * Checks if the key exists and is valid (not expired).
   */
  const has = (key: string, nowMs: number): boolean => {
    // This must reflect even 'undefined' values being set. The existence check handles this.
    return isEntryValid(key, nowMs);
  };

  /**
   * Removes the key from the cache if it exists.
   * @returns True if an entry was removed, false otherwise.
   */
  const deleteKey = (key: string): boolean => {
    if (cache.has(key)) {
      // We must check validity/expiration here implicitly? No, simple deletion is enough.
      cache.delete(key);
      return true;
    }
    return false;
  };

  /**
   * Counts the number of non-expired entries in the cache at a given time.
   */
  const size = (nowMs: number): number => {
    let count = 0;
    for (const [key, entry] of cache.entries()) {
      if (entry.expiresAt >= nowMs) {
        count++;
      } else {
          // Optional cleanup during sizing, though not strictly required by specification, it keeps the cache clean.
          cache.delete(key);
      }
    }
    return count;
  };

  /**
   * Removes all entries from the cache.
   */
  const clear = (): void => {
    cache.clear();
  };


  // --- Required Interface implementation structure ---

  /** @type {TtlCache} */
  const ttlCacheInstance: TtlCache = {
    set: (key, value, nowMs, ttlMs) => set(key as string, value as unknown, nowMs as number, ttlMs as number),
    get: (key, nowMs) => get(key as string, nowMs as number),
    has: (key, nowMs) => has(key as string, nowMs as number),
    delete: (key) => deleteKey(key as string),
    size: (nowMs) => size(nowMs as number),
    clear: () => clear(),
  };

  return ttlCacheInstance;
}

