}

class CalculatorImpl implements Calculator {
    private value = 0;
    private memory = 0;

    add(n: number): this {
        this.value += n;
        return this;
    }

    subtract(n: number): this {
        this.value -= n;
        return this;
    }

    multiply(n: number): this {
        this.value *= n;
        return this;
    }

    divide(n: number): this {
        this.value /= n;
        return this;
    }

    clear(): this {
        this.value = 0;
        return this;
    }

    result(): number {
        return this.value;
    }

    memoryStore(): this {
        this.memory = this.value;
        return this;
    }

    memoryAdd(): this {
        this.memory += this.value;
        return this;
    }

    memoryClear(): this {
        this.memory = 0;
        return this;
    }

    memoryRecall(): number {
        return this.memory;
    }
}

