export function createCalculator(): Calculator {
  let current = 0;
  let memory = 0;

  const calc: Calculator = {
    add(this: Calculator, n: number) { current += n; return this; },
    subtract(this: Calculator, n: number) { current -= n; return this; },
    multiply(this: Calculator, n: number) { current *= n; return this; },
    divide(this: Calculator, n: number) { current /= n; return this; },
    clear(this: Calculator) { current = 0; return this; },
    result() { return current; },
    memoryStore(this: Calculator) { memory = current; return this; },
    memoryRecall() { return memory; },
    memoryClear(this: Calculator) { memory = 0; return this; },
    memoryAdd(this: Calculator) { memory += current; return this; }
  };

  return calc;
}

export interface EventEmitter {
  on(event: string, listener: (payload: any) => any): number;
  once(event: string, listener: (payload: any) => any): number;
  off(event: string, listener: (payload: any) => any): boolean;
  emit(event: string, payload: any): any[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  type Listener = { fn: (payload: any) => any; once: boolean };
  const map = new Map<string, Listener[]>();

  const getListeners = (event: string): Listener[] => {
    let arr = map.get(event);
    if (!arr) {
      arr = [];
      map.set(event, arr);
    }
    return arr;
  };

  const on = (event: string, listener: (payload: any) => any): number => {
    const arr = getListeners(event);
    arr.push({ fn: listener, once: false });
    return arr.length;
  };

  const once = (event: string, listener: (payload: any) => any): number => {
    const arr = getListeners(event);
    arr.push({ fn: listener, once: true });
    return arr.length;
  };

  const off = (
    event: string,
    listener: (payload: any) => any
  ): boolean => {
    const arr = map.get(event);
    if (!arr) return false;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i].fn === listener) {
        arr.splice(i, 1);
        return true;
      }
    }
    return false;
  };

  const emit = (event: string, payload: any): any[] => {
    const arr = map.get(event);
    if (!arr) return [];
    const results: any[] = [];
    // iterate over a shallow copy to avoid issues with modifications
    for (const l of [...arr]) {
      results.push(l.fn(payload));
      if (l.once) {
        const idx = arr.indexOf(l);
        if (idx !== -1) arr.splice(idx, 1);
      }
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    const arr = map.get(event);
    return arr ? arr.length : 0;
  };

  return { on, once, off, emit, listenerCount };
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<
    string,
    Array<{ fn: Listener; once: boolean }>
  >();

  return {
    on(event, listener) {
      const list = listeners.get(event);
      if (list) {
        list.push({ fn: listener, once: false });
        return list.length;
      } else {
        listeners.set(event, [{ fn: listener, once: false }]);
        return 1;
      }
    },

    once(event, listener) {
      const list = listeners.get(event);
      if (list) {
        list.push({ fn: listener, once: true });
        return list.length;
      } else {
        listeners.set(event, [{ fn: listener, once: true }]);
        return 1;
      }
    },

    off(event, listener) {
      const list = listeners.get(event);
      if (!list) return false;
      for (let i = 0; i < list.length; i++) {
        if (list[i].fn === listener) {
          list.splice(i, 1);
          if (list.length === 0) listeners.delete(event);
          else listeners.set(event, list);
          return true;
        }
      }
      return false;
    },

    emit(event, payload) {
      const list = listeners.get(event);
      if (!list) return [];
      const results: unknown[] = [];
      const remaining: Array<{ fn: Listener; once: boolean }> = [];

      for (const item of list) {
        results.push(item.fn(payload));
        if (!item.once) remaining.push(item);
      }

      if (remaining.length === 0) listeners.delete(event);
      else listeners.set(event, remaining);

      return results;
    },

    listenerCount(event) {
      const list = listeners.get(event);
      return list ? list.length : 0;
    },
  };
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createRateLimiter() {
    const store = new Map<string, { start: number; count: number }>();
    const WINDOW_MS = 1000;
    const LIMIT = 3;

    return {
        allow(key: string, nowMs: number): boolean {
            let entry = store.get(key);
            if (!entry) {
                store.set(key, { start: nowMs, count: 1 });
                return true;
            }

            if (nowMs - entry.start >= WINDOW_MS) {
                entry.start = nowMs;
                entry.count = 1;
                return true;
            } else {
                if (entry.count < LIMIT) {
                    entry.count++;
                    return true;
                }
                return false;
            }
        },

        remaining(key: string, nowMs: number): number {
            const entry = store.get(key);
            if (!entry) return LIMIT;

            if (nowMs - entry.start >= WINDOW_MS) {
                return LIMIT;
            } else {
                const rem = LIMIT - entry.count;
                return rem >= 0 ? rem : 0;
            }
        },

        reset(key: string): void {
            store.delete(key);
        },
    };
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state.get(key);
      if (!entry) {
        state.set(key, { count: 1, windowStart: nowMs });
        return true;
      }
      if (nowMs - entry.windowStart >= windowMs) {
        // start new window
        state.set(key, { count: 1, windowStart: nowMs });
        return true;
      }
      if (entry.count < limit) {
        entry.count += 1;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = state.get(key);
      if (!entry) {
        return limit;
      }
      if (nowMs - entry.windowStart >= windowMs) {
        // Window expired; full quota available
        return limit;
      }
      const rem = limit - entry.count;
      return rem > 0 ? rem : 0;
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
