  memoryRecall(): number;
}

export function createCalculator(): Calculator {
  let current = 0;
  let memory = 0;

  const calc = {
    add(n: number): typeof calc {
      current += n;
      return calc;
    },
    subtract(n: number): typeof calc {
      current -= n;
      return calc;
    },
    multiply(n: number): typeof calc {
      current *= n;
      return calc;
    },
    divide(n: number): typeof calc {
      if (n === 0) throw new Error("Division by zero");
      current /= n;
      return calc;
    },
    clear(): typeof calc {
      current = 0;
      return calc;
    },
    result(): number {
      return current;
    },

    memoryStore(): typeof calc {
      memory = current;
      return calc;
    },
    memoryAdd(): typeof calc {
      memory += current;
      return calc;
    },
    memoryClear(): typeof calc {
      memory = 0;
      return calc;
    },
    memoryRecall(): number {
      return memory;
    },
  };

  return calc as Calculator;
}

