  };

  return self;
}

export function createEventEmitter() {
    type Listener = { fn: (payload?: any) => unknown; once: boolean };
    const registry = new Map<string, Listener[]>();

    return {
        on(event: string, listener: (payload?: any) => unknown) {
            const list = registry.get(event) ?? [];
            list.push({ fn: listener, once: false });
            registry.set(event, list);
            return list.length;
        },

        once(event: string, listener: (payload?: any) => unknown) {
            const list = registry.get(event) ?? [];
            list.push({ fn: listener, once: true });
            registry.set(event, list);
            return list.length;
        },

        off(event: string, listener: (payload?: any) => unknown): boolean {
            const list = registry.get(event);
            if (!list) return false;

            for (let i = 0; i < list.length; i++) {
                if (list[i].fn === listener) {
                    list.splice(i, 1);
                    if (list.length === 0) registry.delete(event);
                    else registry.set(event, list);
                    return true;
                }
            }
            return false;
        },

        emit(event: string, payload?: any): unknown[] {
            const list = registry.get(event);
            if (!list || list.length === 0) return [];

            const results: unknown[] = [];
            // Iterate while handling once listeners
            for (let i = 0; i < list.length; ) {
                const { fn, once } = list[i];
                results.push(fn(payload));
                if (once) {
                    list.splice(i, 1);
                } else {
                    i++;
                }
            }

            return results;
        },

        listenerCount(event: string): number {
            return registry.get(event)?.length ?? 0;
        },
    };
}

export function createEventEmitter(): EventEmitter {
  // Internal storage of listeners: event name → array of listener objects
  const _listeners = new Map<
    string,
    Array<{ fn: Listener; once: boolean }>
  >();

  const on = (event: string, listener: Listener): number => {
    const arr = _listeners.get(event) ?? [];
    arr.push({ fn: listener, once: false });
    _listeners.set(event, arr);
    return arr.length;
  };

  const once = (event: string, listener: Listener): number => {
    const arr = _listeners.get(event) ?? [];
    arr.push({ fn: listener, once: true });
    _listeners.set(event, arr);
    return arr.length;
  };

  const off = (event: string, listener: Listener): boolean => {
    const arr = _listeners.get(event);
    if (!arr) return false;
    const idx = arr.findIndex((l) => l.fn === listener);
    if (idx < 0) return false;
    arr.splice(idx, 1);
    if (arr.length === 0) _listeners.delete(event);
    else _listeners.set(event, arr);
    return true;
  };

  const emit = (event: string, payload: unknown): unknown[] => {
    const arr = _listeners.get(event) ?? [];
    // Iterate over a snapshot to avoid mutation issues
    const results: unknown[] = [];
    for (const lObj of [...arr]) {
      results.push(lObj.fn(payload));
      if (lObj.once) off(event, lObj.fn);
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    const arr = _listeners.get(event);
    return arr ? arr.length : 0;
  };

  return { on, once, off, emit, listenerCount };
}

type Listener = (_payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

const WINDOW_SIZE_MS = 1000;
const MAX_REQUESTS_PER_WINDOW = 3;

interface KeyState {
    windowStart: number;
    count: number;
}

export function createRateLimiter() {
    const states = new Map<string, KeyState>();

    return {
        allow(key: string, nowMs: number): boolean {
            const currentWindow = Math.floor(nowMs / WINDOW_SIZE_MS) * WINDOW_SIZE_MS;
            let state = states.get(key);

            if (!state || state.windowStart !== currentWindow) {
                // New window
                states.set(key, { windowStart: currentWindow, count: 1 });
                return true;
            }

            if (state.count < MAX_REQUESTS_PER_WINDOW) {
                state.count += 1;
                return true;
            }

            return false;
        },

        remaining(key: string, nowMs: number): number {
            const currentWindow = Math.floor(nowMs / WINDOW_SIZE_MS) * WINDOW_SIZE_MS;
            const state = states.get(key);

            if (!state || state.windowStart !== currentWindow) {
                return MAX_REQUESTS_PER_WINDOW;
            }

            const remaining = MAX_REQUESTS_PER_WINDOW - state.count;
            return remaining > 0 ? remaining : 0;
        },

        reset(key: string): void {
            states.delete(key);
        },
    };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

const LIMIT = 3;
const WINDOW_MS = 1000;

export function createRateLimiter(): RateLimiter {
  const stateByKey = new Map<
    string,
    { windowStartMs: number; count: number }
  >();

  return {
    allow(key, nowMs) {
      let entry = stateByKey.get(key);
      if (!entry || nowMs - entry.windowStartMs >= WINDOW_MS) {
        // start a fresh window
        stateByKey.set(key, { windowStartMs: nowMs, count: 1 });
        return true;
      }
      if (entry.count < LIMIT) {
        entry.count += 1;
        return true;
      }
      return false;
    },

    remaining(key, nowMs) {
      const entry = stateByKey.get(key);
      if (!entry || nowMs - entry.windowStartMs >= WINDOW_MS) {
        // fresh window: all quota available
        return LIMIT;
      }
      const rem = LIMIT - entry.count;
      return rem > 0 ? rem : 0;
    },

    reset(key) {
      stateByKey.delete(key);
    },
  };
}

