export type Listener = (payload: any) => any;

export interface EventEmitter {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, payload?: any): any[];
    listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
    type Wrapper = { listener: Listener; once: boolean };
    const events = new Map<string, Wrapper[]>();

    return {
        on(event: string, listener: Listener): number {
            const list = events.get(event) ?? [];
            list.push({ listener, once: false });
            events.set(event, list);
            return list.length;
        },

        once(event: string, listener: Listener): number {
            const list = events.get(event) ?? [];
            list.push({ listener, once: true });
            events.set(event, list);
            return list.length;
        },

        off(event: string, listener: Listener): boolean {
            const list = events.get(event);
            if (!list) return false;
            const idx = list.findIndex(e => e.listener === listener);
            if (idx === -1) return false;
            list.splice(idx, 1);
            if (list.length === 0) {
                events.delete(event);
            } else {
                events.set(event, list);
            }
            return true;
        },

        emit(event: string, payload: any = undefined): any[] {
            const originalList = events.get(event);
            if (!originalList) return [];
            const results: any[] = [];
            // Create a snapshot to allow modifications during iteration
            const snapshot = [...originalList];
            for (const wrapped of snapshot) {
                try {
                    results.push(wrapped.listener(payload));
                } catch (e) {
                    // Propagate exception as is; emit may halt on error.
                    throw e;
                }
            }
            // Remove one-time listeners after invocation
            const remaining = originalList.filter(l => !l.once);
            if (remaining.length > 0) {
                events.set(event, remaining);
            } else {
                events.delete(event);
            }
            return results;
        },

        listenerCount(event: string): number {
            const list = events.get(event);
            return list ? list.length : 0;
        },
    };
}

