class SimpleEventEmitter implements EventEmitter {
  private listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  on(event: string, listener: Listener): number {
    const arr = this.listeners.get(event) ?? [];
    arr.push({ fn: listener, once: false });
    this.listeners.set(event, arr);
    return arr.length;
  }

  once(event: string, listener: Listener): number {
    const arr = this.listeners.get(event) ?? [];
    arr.push({ fn: listener, once: true });
    this.listeners.set(event, arr);
    return arr.length;
  }

  off(event: string, listener: Listener): boolean {
    const arr = this.listeners.get(event);
    if (!arr) return false;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i].fn === listener) {
        arr.splice(i, 1);
        if (arr.length === 0) this.listeners.delete(event);
        else this.listeners.set(event, arr);
        return true;
      }
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const arr = this.listeners.get(event);
    if (!arr) return [];
    const results: unknown[] = [];
    const toRemove: number[] = [];
    for (let i = 0; i < arr.length; i++) {
      const { fn, once } = arr[i];
      results.push(fn(payload));
      if (once) toRemove.unshift(i);
    }
    for (const idx of toRemove) {
      arr.splice(idx, 1);
    }
    if (arr.length === 0) this.listeners.delete(event);
    else this.listeners.set(event, arr);
    return results;
  }

  listenerCount(event: string): number {
    const arr = this.listeners.get(event);
    return arr ? arr.length : 0;
  }
}

export function createRateLimiter() {
    const windows = new Map<string, { windowStart: number; count: number }>();

    const WINDOW_MS = 1000;
    const MAX_COUNT = 3;

    // Helper to get or initialize a key's state
    function getState(key: string) {
        let state = windows.get(key);
        if (!state) {
            state = { windowStart: -WINDOW_MS, count: 0 };
            windows.set(key, state);
        }
        return state;
    }

    // Checks if the current time is within the same window or starts a new one
    function resetIfNeeded(state: { windowStart: number; count: number }, nowMs: number) {
        if (nowMs - state.windowStart >= WINDOW_MS) {
            state.windowStart = nowMs;
            state.count = 0;
        }
    }

    return {
        allow(key: string, nowMs: number) {
            const state = getState(key);
            resetIfNeeded(state, nowMs);
            if (state.count < MAX_COUNT) {
                state.count++;
                return true;
            }
            return false;
        },

        remaining(key: string, nowMs: number) {
            const state = getState(key);
            resetIfNeeded(state, nowMs);
            const rem = MAX_COUNT - state.count;
            return rem >= 0 ? rem : 0;
        },

        reset(key: string) {
            windows.delete(key);
        },
    } as const;
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const data = new Map<string, { count: number; start: number }>();
  const limit = 3;
  const windowMs = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = data.get(key);
      if (!entry) {
        entry = { count: 1, start: nowMs };
        data.set(key, entry);
        return true;
      }

      if (nowMs - entry.start >= windowMs) {
        // Start new window
        entry.count = 1;
        entry.start = nowMs;
        data.set(key, entry);
        return true;
      }

      if (entry.count < limit) {
        entry.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = data.get(key);
      if (!entry) {
        return limit;
      }

      if (nowMs - entry.start >= windowMs) {
        // Window has expired; reset count for computation
        return limit;
      }

      const rem = limit - entry.count;
      return rem > 0 ? rem : 0;
    },

    reset(key: string): void {
      data.delete(key);
    },
  };
}

