export function createTtlCache() {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const expireAt = nowMs + (ttlMs ?? 1000);
      cache.set(key, { value, expiresAt: expireAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        cache.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        cache.delete(key);
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      // Delete regardless of expiration state; Map.delete returns true iff key existed.
      return cache.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const [k, entry] of cache.entries()) {
        if (nowMs >= entry.expiresAt) {
          cache.delete(k);
        } else {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      cache.clear();
    },
  };
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const map = new Map<string, { value: unknown; expiresAt: number }>();
  const DEFAULT_TTL_MS = 1000;

  function purge(key?: string) {
    if (key !== undefined) {
      const entry = map.get(key);
      if (!entry) return;
      if (Date.now() >= entry.expiresAt) map.delete(key);
    } else {
      for (const [k, v] of map.entries()) {
        if (Date.now() >= v.expiresAt) map.delete(k);
      }
    }
  }

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const ttl = ttlMs === undefined ? DEFAULT_TTL_MS : ttlMs;
      const expiresAt = nowMs + ttl;
      map.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number) {
      const entry = map.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number) {
      const entry = map.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return false;
      }
      return true;
    },
    delete(key: string) {
      const exists = this.has(key, Date.now());
      if (!exists) return false;
      return map.delete(key);
    },
    size(nowMs: number) {
      let count = 0;
      for (const [k, v] of map.entries()) {
        if (nowMs < v.expiresAt) count++;
        else map.delete(k); // purge expired
      }
      return count;
    },
    clear() {
      map.clear();
    },
  } as TtlCache;
}

