export function createEventEmitter() {
  type Listener = (...args: any[]) => any;
  interface ListenerEntry {
    fn: Listener;
    once: boolean;
  }

  const events = new Map<string, ListenerEntry[]>();

  const on = (event: string, listener: Listener): number => {
    const list = events.get(event) ?? [];
    list.push({ fn: listener, once: false });
    events.set(event, list);
    return list.length;
  };

  const once = (event: string, listener: Listener): number => {
    const list = events.get(event) ?? [];
    list.push({ fn: listener, once: true });
    events.set(event, list);
    return list.length;
  };

  const off = (event: string, listener: Listener): boolean => {
    const list = events.get(event);
    if (!list) return false;
    for (let i = 0; i < list.length; i++) {
      if (list[i].fn === listener) {
        list.splice(i, 1);
        if (list.length === 0) events.delete(event);
        else events.set(event, list);
        return true;
      }
    }
    return false;
  };

  const emit = (event: string, ...payload: any[]): any[] => {
    const list = events.get(event);
    if (!list) return [];
    const results: any[] = [];
    // Use a copy to avoid mutating during iteration due to once removal
    for (const entry of [...list]) {
      if (entry.once) off(event, entry.fn);
      results.push(entry.fn(...payload));
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    const list = events.get(event);
    return list ? list.length : 0;
  };

  return { on, once, off, emit, listenerCount } as const;
}

