export function createEventEmitter(): EventEmitter {
  const events = new Map<string, [Listener, boolean]>();

  function on(event: string, listener: Listener): number {
    let listeners = events.get(event);
    if (!listeners) {
      listeners = [];
      events.set(event, listeners);
    }
    listeners.push([listener, false]);
    return listeners.length;
  }

  function once(event: string, listener: Listener): number {
    let listeners = events.get(event);
    if (!listeners) {
      listeners = [];
      events.set(event, listeners);
    }
    listeners.push([listener, true]);
    return listeners.length;
  }

  function off(event: string, listener: Listener): boolean {
    const listeners = events.get(event);
    if (!listeners) return false;
    for (let i = 0; i < listeners.length; i++) {
      if (listeners[i][0] === listener) {
        listeners.splice(i, 1);
        return true;
      }
    }
    return false;
  }

  function emit(event: string, payload: unknown): unknown[] {
    const listeners = events.get(event);
    if (!listeners) return [];
    const results: unknown[] = [];
    const toRemoveIndices: number[] = [];
    for (let i = 0; i < listeners.length; i++) {
      const [fn, onceFlag] = listeners[i];
      results.push(fn(payload));
      if (onceFlag) toRemoveIndices.push(i);
    }
    // Remove one-time listeners in reverse order
    for (let i = toRemoveIndices.length - 1; i >= 0; i--) {
      listeners.splice(toRemoveIndices[i], 1);
    }
    return results;
  }

  function listenerCount(event: string): number {
    const listeners = events.get(event);
    return listeners ? listeners.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}

export function createRateLimiter() {
    const limit = 3;
    const windowMs = 1000;

    // key → { start: number, count: number }
    const state = new Map<string, { start: number; count: number }>();

    return {
        allow(key: string, nowMs: number): boolean {
            let entry = state.get(key);
            if (!entry) {
                // first request starts a window
                state.set(key, { start: nowMs, count: 1 });
                return true;
            }
            const elapsed = nowMs - entry.start;
            if (elapsed >= windowMs) {
                // window expired – start anew
                entry.start = nowMs;
                entry.count = 1;
                return true;
            }
            if (entry.count < limit) {
                entry.count++;
                return true;
            }
            return false;
        },
        remaining(key: string, nowMs: number): number {
            let entry = state.get(key);
            if (!entry) {
                return limit;
            }
            const elapsed = nowMs - entry.start;
            if (elapsed >= windowMs) {
                // fresh window
                return limit;
            }
            const remaining = limit - entry.count;
            return remaining < 0 ? 0 : remaining;
        },
        reset(key: string): void {
            state.delete(key);
        }
    };
}

