export function createRateLimiter() {
    const state = new Map<string, { windowStart: number; count: number }>();
    const MAX_REQUESTS = 3;
    const WINDOW_MS = 1000;

    return {
        allow(key: string, nowMs: number): boolean {
            let currentState = state.get(key);

            // Initialize state for new keys
            if (!currentState) {
                currentState = { windowStart: nowMs, count: 0 };
                state.set(key, currentState);
            }

            // Boundary rule: when a window has fully elapsed, the next call starts a fresh window.
            // Window range is [windowStart, windowStart + WINDOW_MS).
            if (nowMs >= currentState.windowStart + WINDOW_MS) {
                currentState.windowStart = nowMs;
                currentState.count = 0;
            }

            // Check quota
            if (currentState.count < MAX_REQUESTS) {
                currentState.count++;
                return true;
            }

            return false;
        },

        remaining(key: string, nowMs: number): number {
            const currentState = state.get(key);

            // If key does not exist, full quota is available
            if (!currentState) {
                return MAX_REQUESTS;
            }

            // If window has elapsed, full quota is available (logically fresh window)
            if (nowMs >= currentState.windowStart + WINDOW_MS) {
                return MAX_REQUESTS;
            }

            const remainingCount = MAX_REQUESTS - currentState.count;
            // Ensure non-negative return value
            return Math.max(0, remainingCount);
        },

        reset(key: string): void {
            state.delete(key);
        }
    };
}
