export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const store = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = store.get(key);

      if (!entry || nowMs - entry.windowStart >= windowMs) {
        entry = { windowStart: nowMs, count: 1 };
        store.set(key, entry);
        return true;
      }

      if (entry.count < limit) {
        entry.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = store.get(key);

      if (!entry || nowMs - entry.windowStart >= windowMs) {
        return limit;
      }

      const rem = limit - entry.count;
      return rem < 0 ? 0 : rem;
    },

    reset(key: string): void {
      store.delete(key);
    }
  };
}
