type Listener = (payload?: unknown) => unknown;

interface ListenerEntry {
    fn: Listener;
    once: boolean;
}

export function createEventEmitter() {
    const store = new Map<string, ListenerEntry[]>();

    function getListeners(event: string): ListenerEntry[] {
        if (!store.has(event)) {
            store.set(event, []);
        }
        return store.get(event)!;
    }

    return {
        on(event: string, listener: Listener): number {
            const entries = getListeners(event);
            entries.push({ fn: listener, once: false });
            return entries.length;
        },

        once(event: string, listener: Listener): number {
            const entries = getListeners(event);
            entries.push({ fn: listener, once: true });
            return entries.length;
        },

        off(event: string, listener: Listener): boolean {
            const entries = store.get(event);
            if (!entries) {
                return false;
            }
            const idx = entries.findIndex(e => e.fn === listener);
            if (idx === -1) {
                return false;
            }
            entries.splice(idx, 1);
            return true;
        },

        emit(event: string, payload?: unknown): unknown[] {
            const entries = store.get(event);
            if (!entries) {
                return [];
            }
            const onceIndices: number[] = [];
            const results: unknown[] = [];
            for (let i = 0; i < entries.length; i++) {
                const entry = entries[i];
                if (entry.once) {
                    onceIndices.push(i);
                }
                results.push(entry.fn(payload));
            }
            // Remove once listeners in reverse order to preserve indices
            for (let i = onceIndices.length - 1; i >= 0; i--) {
                entries.splice(onceIndices[i], 1);
            }
            return results;
        },

        listenerCount(event: string): number {
            const entries = store.get(event);
            if (!entries) {
                return 0;
            }
            return entries.length;
        },
    };
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>()

  function addListener(event: string, listener: Listener, once: boolean): number {
    const list = listeners.get(event) ?? []
    list.push({ fn: listener, once })
    listeners.set(event, list)
    return list.length
  }

  return {
    on(event, listener) {
      return addListener(event, listener, false)
    },

    once(event, listener) {
      return addListener(event, listener, true)
    },

    off(event, listener) {
      const list = listeners.get(event)
      if (!list) {
        return false
      }
      const idx = list.findIndex(entry => entry.fn === listener)
      if (idx === -1) {
        return false
      }
      list.splice(idx, 1)
      return true
    },

    emit(event, payload) {
      const list = listeners.get(event) ?? []
      const results: unknown[] = []
      const toRemove: number[] = []

      for (let i = 0; i < list.length; i++) {
        const entry = list[i]
        if (entry.once) {
          toRemove.push(i)
        }
        results.push(entry.fn(payload))
      }

      for (let i = toRemove.length - 1; i >= 0; i--) {
        list.splice(toRemove[i], 1)
      }

      return results
    },

    listenerCount(event) {
      const list = listeners.get(event)
      if (!list) {
        return 0
      }
      return list.length
    },
  }
}

export function createRateLimiter(): {
	allow(key: string, nowMs: number): boolean;
	remaining(key: string, nowMs: number): number;
	reset(key: string): void;
} {
	const MAX_REQUESTS = 3;
	const WINDOW_MS = 1000;

	const state = new Map<string, { windowStart: number; count: number }>();

	function getWindow(key: string, nowMs: number) {
		const current = state.get(key);
		if (!current || nowMs - current.windowStart >= WINDOW_MS) {
			return null;
		}
		return current;
	}

	function setWindow(
		key: string,
		windowStart: number,
		count: number
	) {
		state.set(key, { windowStart, count });
	}

	return {
		allow(key: string, nowMs: number): boolean {
			const current = getWindow(key, nowMs);
			if (!current) {
				setWindow(nowMs, 1);
				return true;
			}
			if (current.count < MAX_REQUESTS) {
				current.count += 1;
				return true;
			}
			return false;
		},

		remaining(key: string, nowMs: number): number {
			const current = getWindow(key, nowMs);
			if (!current) {
				return MAX_REQUESTS;
			}
			const rem = MAX_REQUESTS - current.count;
			return rem < 0 ? 0 : rem;
		},

		reset(key: string): void {
			state.delete(key);
		}
	};
}

