type Listener = (...args: any[]) => any;

interface EventHandler {
  listener: Listener;
  once: boolean;
}

export function createEventEmitter() {
  const handlers = new Map<string, EventHandler[]>();

  return {
    on(event: string, listener: Listener): number {
      const list = handlers.get(event) ?? [];
      list.push({ listener, once: false });
      handlers.set(event, list);
      return list.length;
    },

    once(event: string, listener: Listener): number {
      const list = handlers.get(event) ?? [];
      list.push({ listener, once: true });
      handlers.set(event, list);
      return list.length;
    },

    off(event: string, listener: Listener): boolean {
      const list = handlers.get(event);
      if (!list) return false;
      const idx = list.findIndex((h) => h.listener === listener);
      if (idx === -1) return false;
      list.splice(idx, 1);
      return true;
    },

    emit(event: string, ...args: any[]): any[] {
      const list = handlers.get(event);
      if (!list) return [];
      const results: any[] = [];
      const toRemove: number[] = [];
      for (let i = 0; i < list.length; i++) {
        const h = list[i];
        results.push(h.listener(...args));
        if (h.once) toRemove.push(i);
      }
      for (let i = toRemove.length - 1; i >= 0; i--) {
        list.splice(toRemove[i], 1);
      }
      return results;
    },

    listenerCount(event: string): number {
      const list = handlers.get(event);
      if (!list) return 0;
      return list.length;
    },
  };
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

interface Entry {
  fn: Listener
  once: boolean
}

export function createEventEmitter(): EventEmitter {
  const store = new Map<string, Entry[]>()

  function getListeners(event: string): Entry[] {
    let entries = store.get(event)
    if (!entries) {
      entries = []
      store.set(event, entries)
    }
    return entries
  }

  return {
    on(event, listener) {
      const entries = getListeners(event)
      entries.push({ fn: listener, once: false })
      return entries.length
    },

    once(event, listener) {
      const entries = getListeners(event)
      entries.push({ fn: listener, once: true })
      return entries.length
    },

    off(event, listener) {
      const entries = store.get(event)
      if (!entries) return false
      const idx = entries.findIndex((e) => e.fn === listener)
      if (idx === -1) return false
      entries.splice(idx, 1)
      return true
    },

    emit(event, payload) {
      const entries = store.get(event)
      if (!entries) return []
      const results: unknown[] = []
      let i = 0
      while (i < entries.length) {
        const entry = entries[i]
        results.push(entry.fn(payload))
        if (entry.once) {
          entries.splice(i, 1)
        } else {
          i++
        }
      }
      return results
    },

    listenerCount(event) {
      const entries = store.get(event)
      return entries ? entries.length : 0
    },
  }
}

type KeyState = {
	windowStart: number;
	count: number;
};

export function createRateLimiter() {
	const stores = new Map<string, KeyState>();

	function getWindow(key: string, nowMs: number): KeyState {
		let state = stores.get(key);
		if (state === undefined || nowMs - state.windowStart >= 1000) {
			state = { windowStart: nowMs, count: 0 };
			stores.set(key, state);
		}
		return state;
	}

	return {
		allow(key: string, nowMs: number): boolean {
			const state = getWindow(key, nowMs);
			if (state.count < 3) {
				state.count += 1;
				return true;
			}
			return false;
		},

		remaining(key: string, nowMs: number): number {
			const state = getWindow(key, nowMs);
			const left = 3 - state.count;
			return Math.max(0, left);
		},

		reset(key: string): void {
			stores.delete(key);
		},
	};
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

const LIMIT = 3;
const WINDOW_MS = 1000;

interface KeyState {
  windowStart: number;
  count: number;
}

export function createRateLimiter(): RateLimiter {
  const state = new Map<string, KeyState>();

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = state.get(key);
      if (entry == null || nowMs - entry.windowStart >= WINDOW_MS) {
        entry = { windowStart: nowMs, count: 0 };
        state.set(key, entry);
      }
      if (entry.count < LIMIT) {
        entry.count++;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = state.get(key);
      if (entry == null || nowMs - entry.windowStart >= WINDOW_MS) {
        return LIMIT;
      }
      const rem = LIMIT - entry.count;
      return rem > 0 ? rem : 0;
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
}

