type Listener = (payload: any) => any;

export function createEventEmitter() {
  const listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  function addRaw(event: string, fn: Listener, once: boolean): number {
    const list = listeners.get(event) || [];
    list.push({ fn, once });
    listeners.set(event, list);
    return list.length;
  }

  function on(event: string, listener: Listener): number {
    return addRaw(event, listener, false);
  }

  function once(event: string, listener: Listener): number {
    return addRaw(event, listener, true);
  }

  function off(event: string, listener: Listener): boolean {
    const list = listeners.get(event);
    if (!list) return false;
    const idx = list.findIndex(
      (entry) => entry.fn === listener
    );
    if (idx === -1) return false;
    list.splice(idx, 1);
    list.length === 0 ? listeners.delete(event) : null;
    return true;
  }

  function emit(event: string, payload: any): any[] {
    const list = listeners.get(event);
    if (!list) return [];
    const results: any[] = [];
    const toRemove: number[] = [];
    for (let i = 0; i < list.length; i++) {
      const entry = list[i];
      if (entry.once) {
        toRemove.push(i);
      }
      try {
        results.push(entry.fn(payload));
      } catch (_) {}
    }
    for (let i = toRemove.length - 1; i >= 0; i--) {
      list.splice(toRemove[i], 1);
    }
    if (list.length === 0) {
      listeners.delete(event);
    }
    return results;
  }

  function listenerCount(event: string): number {
    const list = listeners.get(event);
    return list ? list.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

interface InternalListener {
  fn: Listener
  once: boolean
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, InternalListener[]>()

  function register(event: string, entry: InternalListener): void {
    const bucket = listeners.get(event)
    if (bucket) {
      bucket.push(entry)
    } else {
      listeners.set(event, [entry])
    }
  }

  return {
    on(event, listener) {
      register(event, { fn: listener, once: false })
      return listeners.get(event)!.length
    },

    once(event, listener) {
      register(event, { fn: listener, once: true })
      return listeners.get(event)!.length
    },

    off(event, listener) {
      const bucket = listeners.get(event)
      if (!bucket) return false
      const idx = bucket.findIndex(l => l.fn === listener)
      if (idx === -1) return false
      bucket.splice(idx, 1)
      return true
    },

    emit(event, payload) {
      const bucket = listeners.get(event)
      if (!bucket) return []
      const results: unknown[] = []
      const toRemove: number[] = []
      for (let i = 0; i < bucket.length; i++) {
        const entry = bucket[i]
        const ret = entry.fn(payload)
        results.push(ret)
        if (entry.once) {
          toRemove.push(i)
        }
      }
      for (let i = toRemove.length - 1; i >= 0; i--) {
        bucket.splice(toRemove[i], 1)
      }
      return results
    },

    listenerCount(event) {
      const bucket = listeners.get(event)
      return bucket ? bucket.length : 0
    }
  }
}

interface WindowState {
  windowStart: number;
  count: number;
}

export function createRateLimiter(): {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
} {
  const LIMIT = 3;
  const WINDOW_MS = 1000;
  const state = new Map<string, WindowState>();

  function getOrInitWindowState(key: string, nowMs: number): WindowState {
    let entry = state.get(key);
    if (!entry || nowMs - entry.windowStart >= WINDOW_MS) {
      entry = { windowStart: nowMs, count: 0 };
      state.set(key, entry);
    }
    return entry;
  }

  function allow(key: string, nowMs: number): boolean {
    const entry = getOrInitWindowState(key, nowMs);
    if (entry.count < LIMIT) {
      entry.count++;
      return true;
    }
    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const entry = getOrInitWindowState(key, nowMs);
    const left = LIMIT - entry.count;
    return left < 0 ? 0 : left;
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, remaining, reset };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const store = new Map<string, { windowStart: number; count: number }>()

  return {
    allow(key, nowMs) {
      let entry = store.get(key)
      if (!entry || nowMs - entry.windowStart >= windowMs) {
        entry = { windowStart: nowMs, count: 0 }
        store.set(key, entry)
      }
      if (entry.count < limit) {
        entry.count++
        return true
      }
      return false
    },
    remaining(key, nowMs) {
      const entry = store.get(key)
      if (!entry || nowMs - entry.windowStart >= windowMs) {
        return limit
      }
      return Math.max(0, limit - entry.count)
    },
    reset(key) {
      store.delete(key)
    }
  }
}

