export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const store = new Map<string, { value: unknown; expiresAt: number }>()
  const present = new Set<string>()

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      present.add(key)
      store.set(key, {
        value,
        expiresAt: nowMs + ttlMs,
      })
    },

    get(key, nowMs) {
      const entry = store.get(key)
      if (!entry || !present.has(key)) return undefined
      if (nowMs >= entry.expiresAt) {
        present.delete(key)
        store.delete(key)
        return undefined
      }
      return entry.value
    },

    has(key, nowMs) {
      const entry = store.get(key)
      if (!entry || !present.has(key)) return false
      if (nowMs >= entry.expiresAt) {
        present.delete(key)
        store.delete(key)
        return false
      }
      return true
    },

    delete(key) {
      const existed = present.has(key)
      present.delete(key)
      store.delete(key)
      return existed
    },

    size(nowMs) {
      let count = 0
      for (const key of present) {
        const entry = store.get(key)
        if (entry && nowMs < entry.expiresAt) {
          count++
        } else {
          present.delete(key)
          store.delete(key)
        }
      }
      return count
    },

    clear() {
      store.clear()
      present.clear()
    },
  }
}

interface Entry {
  value: unknown
  expiresAt: number
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  const store = new Map<string, Entry>()
  const defaultTtlMs = 1000

  return {
    set(key, value, nowMs, ttlMs = defaultTtlMs) {
      store.set(key, {
        value,
        expiresAt: nowMs + ttlMs
      })
    },

    get(key, nowMs) {
      const entry = store.get(key)
      if (entry === undefined || nowMs >= entry.expiresAt) {
        return undefined
      }
      return entry.value
    },

    has(key, nowMs) {
      const entry = store.get(key)
      if (entry === undefined || nowMs >= entry.expiresAt) {
        return false
      }
      return true
    },

    delete(key) {
      return store.delete(key)
    },

    size(nowMs) {
      let count = 0
      for (const entry of store.values()) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },

    clear() {
      store.clear()
    }
  }
}

