type Listener = (...args: any[]) => any;

interface _Handler {
  listener: Listener;
  once: boolean;
}

export function createEventEmitter() {
  const registry = new Map<string, _Handler[]>();

  return {
    on(event: string, listener: Listener): number {
      let handlers = registry.get(event);
      if (!handlers) {
        handlers = [];
        registry.set(event, handlers);
      }
      handlers.push({ listener, once: false });
      return handlers.length;
    },

    once(event: string, listener: Listener): number {
      let handlers = registry.get(event);
      if (!handlers) {
        handlers = [];
        registry.set(event, handlers);
      }
      handlers.push({ listener, once: true });
      return handlers.length;
    },

    off(event: string, listener: Listener): boolean {
      const handlers = registry.get(event);
      if (!handlers) return false;
      const index = handlers.findIndex(h => h.listener === listener);
      if (index !== -1) {
        handlers.splice(index, 1);
        return true;
      }
      return false;
    },

    emit(event: string, payload: any): any[] {
      const handlers = registry.get(event);
      if (!handlers || handlers.length === 0) return [];

      const results: any[] = [];
      for (const handler of handlers) {
        results.push(handler.listener(payload));
      }

      const remaining = handlers.filter(h => !h.once);
      registry.set(event, remaining);
      return results;
    },

    listenerCount(event: string): number {
      const handlers = registry.get(event);
      return handlers ? handlers.length : 0;
    }
  };
}

