      if (!regs) {
        regs = [];
        map.set(event, regs);
      }
      regs.push({ fn: listener, once: false });
      return regs.length;
    },

    once(event: string, listener: Listener): number {
      let regs = map.get(event);
      if (!regs) {
        regs = [];
        map.set(event, regs);
      }
      regs.push({ fn: listener, once: true });
      return regs.length;
