interface LimiterState {
  windowStartMs: number;
  remaining: number;
}

export function createRateLimiter() {
  const quotas = new Map<string, LimiterState>();

  return {
    allow(key: string, nowMs: number): boolean {
      let state = quotas.get(key);

      const isNewKey = !state;
      const isWindowElapsed = state && nowMs >= state.windowStartMs + 1000;

      if (isNewKey || isWindowElapsed) {
        if (state) {
          state.windowStartMs = nowMs;
          state.remaining = 3;
        } else {
          const newState: LimiterState = { windowStartMs: nowMs, remaining: 3 };
          quotas.set(key, newState);
          state = newState;
        }
      }

      if (state && state.remaining > 0) {
        state.remaining--;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = quotas.get(key);

      if (!state) {
        return 3;
      }

      if (nowMs >= state.windowStartMs + 1000) {
        return 3;
      }

      return Math.max(0, state.remaining);
    },

    reset(key: string): void {
      quotas.delete(key);
    }
  };
}

