export type Listener = (...args: unknown[]) => unknown;

interface EventMap {
  [event: string]: Array<Listener>;
}

type OnceListener = Listener & { __once: true };

function createEventEmitter(): {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, ...args: unknown[]): unknown[];
  listenerCount(event: string): number;
} {
  const store: EventMap = Object.create(null);

  function on(event: string, listener: Listener): number {
    if (!(event in store)) {
      store[event] = [];
    }
    store[event].push(listener);
    return store[event].length;
  }

  function once(event: string, listener: Listener): number {
    const wrapper: OnceListener = Object.assign(
      (...args: unknown[]) => {
        off(event, wrapper);
        return listener(...args);
      },
      { __once: true as const }
    );
    return on(event, wrapper);
  }

  function off(event: string, listener: Listener): boolean {
    const listeners = store[event];
    if (!listeners) return false;

    for (let i = 0; i < listeners.length; i++) {
      const candidate = listeners[i];
      if (candidate === listener || (candidate as OnceListener).__once) {
        listeners.splice(i, 1);
        if (listeners.length === 0) {
          delete store[event];
        }
        return true;
      }
    }

    return false;
  }

  function emit(event: string, ...args: unknown[]): unknown[] {
    const listeners = store[event];
    if (!listeners || listeners.length === 0) return [];

    const results: unknown[] = new Array(listeners.length);
    for (let i = 0; i < listeners.length; i++) {
      results[i] = listeners[i](...args);
    }
    return results;
  }

  function listenerCount(event: string): number {
    const listeners = store[event];
    return listeners ? listeners.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}

export { createEventEmitter };

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Listener[]>();

  function on(event: string, listener: Listener): number {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const arr = listeners.get(event)!;
    arr.push(listener);
    return arr.length;
  }

  function once(event: string, listener: Listener): number {
    const wrapper = (payload: unknown) => {
      off(event, wrapper);
      listener(payload);
    };
    return on(event, wrapper);
  }

  function off(event: string, listener: Listener): boolean {
    const arr = listeners.get(event);
    if (!arr || arr.length === 0) {
      return false;
    }
    const index = arr.indexOf(listener);
    if (index === -1) {
      return false;
    }
    arr.splice(index, 1);
    if (arr.length === 0) {
      listeners.delete(event);
    }
    return true;
  }

  function emit(event: string, payload: unknown): unknown[] {
    const arr = listeners.get(event);
    if (!arr || arr.length === 0) {
      return [];
    }
    const snapshot = Array.from(arr);
    const results: unknown[] = [];
    for (const fn of snapshot) {
      try {
        results.push(fn(payload));
      } catch {
        // Swallow errors to ensure remaining listeners are invoked
      }
    }
    return results;
  }

  function listenerCount(event: string): number {
    const arr = listeners.get(event);
    return arr ? arr.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}

const LIMIT = 3;
const WINDOW_MS = 1000;

interface KeyState {
  count: number;
  windowStart: number;
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

function createRateLimiter(): RateLimiter {
  const state = new Map<string, KeyState>();

  function ensureFresh(key: string, nowMs: number): KeyState {
    const existing = state.get(key);
    if (!existing || nowMs >= existing.windowStart + WINDOW_MS) {
      const fresh: KeyState = { count: 0, windowStart: nowMs };
      state.set(key, fresh);
      return fresh;
    }
    return existing;
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = ensureFresh(key, nowMs);
      if (entry.count < LIMIT) {
        entry.count += 1;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = ensureFresh(key, nowMs);
      return Math.max(0, LIMIT - entry.count);
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
}

export { createRateLimiter };

export function createRateLimiter(): RateLimiter {
  const WINDOW_MS = 1000;
  const LIMIT = 3;

  interface WindowState {
    startTime: number;
    count: number;
  }

  const windows: Map<string, WindowState> = new Map();

  function getWindow(key: string, nowMs: number): WindowState | null {
    const existing = windows.get(key);
    if (!existing) {
      return null;
    }
    // Boundary reset rule: fresh window when elapsed >= windowMs
    if (nowMs - existing.startTime >= WINDOW_MS) {
      windows.delete(key);
      return null;
    }
    return existing;
  }

  function allow(key: string, nowMs: number): boolean {
    const win = getWindow(key, nowMs);
    if (!win || win.count < LIMIT) {
      // Start new or use existing window
      let targetWin = windows.get(key);
      if (!targetWin) {
        targetWin = { startTime: nowMs, count: 0 };
        windows.set(key, targetWin);
      }
      targetWin.count++;
      return true;
    }
    // Over limit within the window
    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const win = getWindow(key, nowMs);
    if (!win) {
      return LIMIT;
    }
    const remain = LIMIT - win.count;
    return Math.max(0, remain);
  }

  function reset(key: string): void {
    windows.delete(key);
  }

  return { allow, remaining, reset };
}

