export type Todo = {
  id: number;
  text: string;
  completed: boolean;
};

export function createTodoApp() {
  const todos: Array<Todo> = [];
  let nextId = 1;

  return {
    addTodo(text: string): Todo {
      const todo: Todo = { id: nextId++, text, completed: false };
      todos.push(todo);
      return todo;
    },

    getTodo(id: number): Todo | undefined {
      return todos.find((t) => t.id === id);
    },

    toggleTodo(id: number): void {
      const todo = todos.find((t) => t.id === id);
      if (todo !== undefined) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex((t) => t.id === id);
      if (index !== -1) {
        todos.splice(index, 1);
        return true;
      }
      return false;
    },

    listTodos(): Array<Todo> {
      return todos.slice();
    },

    listCompleted(): Array<Todo> {
      return todos.filter((t) => t.completed).slice();
    },

    listPending(): Array<Todo> {
      return todos.filter((t) => !t.completed).slice();
    },

    clearCompleted(): void {
      const remaining: Array<Todo> = [];
      for (let i = 0; i < todos.length; i++) {
        if (!todos[i].completed) {
          remaining.push(todos[i]);
        }
      }
      todos.length = 0;
      for (let j = 0; j < remaining.length; j++) {
        todos.push(remaining[j]);
      }
    },
  };
}

