  text: string;
}

export interface TodoApp {
  add(text: string): void;
  remove(id: number): boolean;
  toggle(id: number): void;
  getAll(): Todo[];
  getCompleted(): Todo[];
  getIdle(): Todo[];
  emptyCompleted(): void;
}

export function createTodoApp(): TodoApp {
  let counter = 0;
  const store: Todo[] = [];

  return {
    add(text: string): void {
      store.push({ id: counter++, text });
    },
    remove(id: number): boolean {
      const idx = store.findIndex(t => t.id === id);
      if (idx !== -1) {
        store.splice(idx, 1);
        return true;
      }
      return false;
    },
    toggle(id: number): void {
      const todo = store.find(t => t.id === id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },
    getAll(): Todo[] {
      return [...store];
    },
    getCompleted(): Todo[] {
      return store.filter(t => t.completed);
    },
    getIdle(): Todo[] {
      return store.filter(t => !t.completed);
    },
    emptyCompleted(): void {
      const batch = store.filter(t => t.completed);
      for (const item of batch) {
        const j = store.indexOf(item);
        if (j !== -1) store.splice(j, 1);
      }
    },
  };
}

