export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const entries = new Map<string, { value: unknown; expiresAt: number }>()
  const DEFAULT_TTL_MS = 1000

  function isLive(entry: { value: unknown; expiresAt: number }, nowMs: number): boolean {
    return nowMs < entry.expiresAt
  }

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = DEFAULT_TTL_MS): void {
      entries.set(key, { value, expiresAt: nowMs + ttlMs })
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key)
      if (!entry || !isLive(entry, nowMs)) {
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key)
      return !!entry && isLive(entry, nowMs)
    },

    delete(key: string): boolean {
      const entry = entries.get(key)
      if (entry) {
        entries.delete(key)
        return true
      }
      return false
    },

    size(nowMs: number): number {
      let count = 0
      for (const entry of entries.values()) {
        if (isLive(entry, nowMs)) {
          count++
        }
      }
      return count
    },

    clear(): void {
      entries.clear()
    },
  }
}

export function createTtlCache(): TtlCache {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const effectiveTtl = ttlMs !== undefined ? ttlMs : 1000;
      if (effectiveTtl === 0) {
        store.delete(key);
        return;
      }
      store.set(key, { value, expiresAt: nowMs + effectiveTtl });
    },

    get(key: string, nowMs: number): unknown {
      const entry = store.get(key);
      if (!entry) {
        return undefined;
      }
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      if (!entry) {
        return false;
      }
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      return store.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of store) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
          store.delete(key);
        }
      }
      return count;
    },

    clear(): void {
      store.clear();
    },
  };
}

