export function createEventEmitter() {
  const listeners: Map<string, Array<{ fn: Function; once: boolean }>> = new Map();

  function getListeners(event: string): Array<{ fn: Function; once: boolean }> {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    return listeners.get(event)!;
  }

  function on(event: string, listener: Function): number {
    const list = getListeners(event);
    list.push({ fn: listener, once: false });
    return list.length;
  }

  function once(event: string, listener: Function): number {
    const list = getListeners(event);
    list.push({ fn: listener, once: true });
    return list.length;
  }

  function off(event: string, listener: Function): boolean {
    const list = listeners.get(event);
    if (!list) return false;
    for (let i = 0; i < list.length; i++) {
      if (list[i].fn === listener) {
        list.splice(i, 1);
        return true;
      }
    }
    return false;
  }

  function emit(event: string, payload?: unknown): unknown[] {
    const list = listeners.get(event);
    if (!list || list.length === 0) return [];
    const results: unknown[] = [];
    for (let i = list.length - 1; i >= 0; i--) {
      if (list[i].once) {
        const removed = list.splice(i, 1)[0];
        results.unshift(removed.fn(payload));
      } else {
        results.push(list[i].fn(payload));
      }
    }
    return results;
  }

  function listenerCount(event: string): number {
    const list = listeners.get(event);
    return list ? list.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}

