    emit(event: string, payload: unknown): unknown[] {
      const listeners = registry.get(event)
      if (!listeners || listeners.length === 0) return []
      const results: unknown[] = []
      for (let i = listeners.length - 1; i >= 0; i--) {
        if (listeners[i].once) {
          listeners.splice(i, 1)
        }
      }
      for (const reg of listeners) {
        results.push(reg.listener(payload))
      }
      return results
    },

    listenerCount(event: string): number {
      const listeners = registry.get(event)
      if (!listeners) return 0
      return listeners.length
    },
  }
}

const WINDOW_MS = 1000;
const MAX_REQUESTS = 3;

interface KeyState {
  windowStart: number;
  used: number;
}

type StateMap = Map<string, KeyState>;

export function createRateLimiter(): {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
} {
  const store: StateMap = new Map();

  function getOrExpireKey(key: string, nowMs: number): KeyState | null {
    const existing = store.get(key);
    if (!existing) {
      return null;
    }
    if (nowMs - existing.windowStart >= WINDOW_MS) {
      store.delete(key);
      return null;
    }
    return existing;
  }

  function ensureWindow(key: string, nowMs: number): KeyState {
    let state = store.get(key);
    if (!state || nowMs - state.windowStart >= WINDOW_MS) {
      state = { windowStart: nowMs, used: 0 };
      store.set(key, state);
    }
    return state;
  }

  function allow(key: string, nowMs: number): boolean {
    const existing = getOrExpireKey(key, nowMs);
    if (existing === null) {
      const newState: KeyState = { windowStart: nowMs, used: 1 };
      store.set(key, newState);
      return true;
    }
    if (existing.used >= MAX_REQUESTS) {
      return false;
    }
    existing.used += 1;
    return true;
  }

  function remaining(key: string, nowMs: number): number {
    const existing = getOrExpireKey(key, nowMs);
    if (existing === null) {
      return MAX_REQUESTS;
    }
    return Math.max(0, MAX_REQUESTS - existing.used);
  }

  function reset(key: string): void {
    store.delete(key);
  }

  return { allow, remaining, reset };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const windows = new Map<string, { count: number; startTime: number }>()

  return {
    allow(key: string, nowMs: number): boolean {
      let win = windows.get(key)

      if (!win || nowMs - win.startTime >= windowMs) {
        windows.set(key, { count: 1, startTime: nowMs })
        return true
      }

      if (win.count < limit) {
        win.count++
        return true
      }

      return false
    },

    remaining(key: string, nowMs: number): number {
      const win = windows.get(key)

      if (!win || nowMs - win.startTime >= windowMs) {
        return limit
      }

      return Math.max(0, limit - win.count)
    },

    reset(key: string): void {
      windows.delete(key)
    }
  }
}

