export function createTodoApp() {
  let nextId = 1;
  const todos: Map<number, { id: number; text: string; completed: boolean }> = new Map();

  function addTodo(text: string): { id: number; text: string; completed: boolean } {
    const id = nextId++;
    const todo = { id, text, completed: false };
    todos.set(id, todo);
    return { ...todo };
  }

  function getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
    const todo = todos.get(id);
    return todo ? { ...todo } : undefined;
  }

  function toggleTodo(id: number): void {
    const todo = todos.get(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  function deleteTodo(id: number): boolean {
    if (todos.has(id)) {
      todos.delete(id);
      return true;
    }
    return false;
  }

  function listTodos(): Array<{ id: number; text: string; completed: boolean }> {
    return Array.from(todos.values()).map((t) => ({ ...t }));
  }

  function listCompleted(): Array<{ id: number; text: string; completed: boolean }> {
    return listTodos().filter((t) => t.completed);
  }

  function listPending(): Array<{ id: number; text: string; completed: boolean }> {
    return listTodos().filter((t) => !t.completed);
  }

  function clearCompleted(): void {
    for (const [id] of todos) {
      if (todos.get(id)!.completed) {
        todos.delete(id);
      }
    }
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
