export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  deleteFn(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const store = new Map<
    string,
    { value: unknown; expiresAt: number }
  >()

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const absTtl = ttlMs ?? 1000
    store.set(key, { value, expiresAt: nowMs + absTtl })
  }

  function get(key: string, nowMs: number): unknown {
    const entry = store.get(key)
    if (!entry || nowMs >= entry.expiresAt) {
      store.delete(key)
      return undefined
    }
    return entry.value
  }

  function has(key: string, nowMs: number): boolean {
    const entry = store.get(key)
    if (!entry) {
      return false
    }
    if (nowMs >= entry.expiresAt) {
      store.delete(key)
      return false
    }
    return true
  }

  function deleteFn(key: string): boolean {
    if (store.has(key)) {
      store.delete(key)
      return true
    }
    return false
  }

  function size(nowMs: number): number {
    let count = 0
    for (const [key, entry] of store) {
      if (nowMs < entry.expiresAt) {
        count++
      } else {
        store.delete(key)
      }
    }
    return count
  }

  function clear(): void {
    store.clear()
  }

  return { set, get, has, delete: deleteFn, size, clear }
}

export function createTtlCache(): TtlCache {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs = 1000): void {
      const expiresAt = ttlMs === 0 ? nowMs - 1 : nowMs + ttlMs;
      store.set(key, { value, expiresAt });
    },

    get(key, nowMs): unknown {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key, nowMs): boolean {
      const entry = store.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return false;
      }
      return true;
    },

    delete(key): boolean {
      return store.delete(key);
    },

    size(nowMs): number {
      let count = 0;
      for (const entry of store.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      store.clear();
    },
  };
}

