export type EventHandler = (...args: unknown[]) => void;

interface CreateEventEmitterResult {
  on(event: string, listener: EventHandler): number;
  once(event: string, listener: EventHandler): number;
  off(event: string, listener: EventHandler): boolean;
  emit(event: string, ...payload: unknown[]): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): CreateEventEmitterResult {
  const normalListeners = new Map<string, Array<EventHandler>>();
  const onceListeners = new Map<string, Array<EventHandler>>();

  function on(event: string, listener: EventHandler): number {
    let handlers = normalListeners.get(event);
    if (!handlers) {
      handlers = [];
      normalListeners.set(event, handlers);
    }
    handlers.push(listener);
    return handlers.length;
  }

  function once(event: string, listener: EventHandler): number {
    let handlers = onceListeners.get(event);
    if (!handlers) {
      handlers = [];
      onceListeners.set(event, handlers);
    }
    handlers.push(listener);
    return handlers.length;
  }

  function off(event: string, listener: EventHandler): boolean {
    const handlers = normalListeners.get(event);
    if (!handlers) {
      return false;
    }
    const index = handlers.indexOf(listener);
    if (index === -1) {
      return false;
    }
    handlers.splice(index, 1);
    if (handlers.length === 0) {
      normalListeners.delete(event);
    }
    return true;
  }

  function emit(event: string, ...payload: unknown[]): unknown[] {
    const results: unknown[] = [];

    const normalHandlers = normalListeners.get(event);
    if (normalHandlers) {
      for (let i = 0; i < normalHandlers.length; i++) {
        results.push(normalHandlers[i](...payload));
      }
    }

    const onceHandlers = onceListeners.get(event);
    if (onceHandlers) {
      for (let i = 0; i < onceHandlers.length; i++) {
        results.push(onceHandlers[i](...payload));
      }
      onceListeners.delete(event);
    }

    return results;
  }

  function listenerCount(event: string): number {
    let count = normalListeners.get(event)?.length ?? 0;
    const onceCount = onceListeners.get(event)?.length ?? 0;
    return count + onceCount;
  }

  return { on, once, off, emit, listenerCount };
}

export type Listener = (payload: unknown) => unknown

export interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const registry = new Map<string, Array<Listener>>()

  function getCount(event: string): number {
    return registry.get(event)?.length ?? 0
  }

  function on(event: string, listener: Listener): number {
    const listeners = registry.get(event) || []
    listeners.push(listener)
    registry.set(event, listeners)
    return getCount(event)
  }

  function once(event: string, listener: Listener): number {
    const wrappedListener: Listener = (...args: unknown[]) => {
      const result = listener(...args) as unknown
      off(event, wrappedListener)
      return result
    }
    const listeners = registry.get(event) || []
    listeners.push(wrappedListener)
    registry.set(event, listeners)
    return getCount(event)
  }

  function off(event: string, listener: Listener): boolean {
    const listeners = registry.get(event)
    if (!listeners) {
      return false
    }
    const index = listeners.indexOf(listener)
    if (index === -1) {
      return false
    }
    listeners.splice(index, 1)
    if (listeners.length > 0) {
      registry.set(event, listeners)
    } else {
      registry.delete(event)
    }
    return true
  }

  function emit(event: string, payload: unknown): unknown[] {
    const listeners = registry.get(event)
    if (!listeners || listeners.length === 0) {
      return []
    }
    registry.set(event, [...listeners])
    return listeners.map(fn => fn(payload))
  }

  function listenerCount(event: string): number {
    return getCount(event)
  }

  return { on, once, off, emit, listenerCount }
}

const WINDOW_SIZE_MS = 1000;
const MAX_REQUESTS = 3;

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

interface WindowState {
  windowStart: number;
  count: number;
}

function createRateLimiter(): RateLimiter {
  const keyStates = new Map<string, WindowState>();

  function getOrCreateKeyState(key: string, nowMs: number): WindowState {
    let state = keyStates.get(key);
    if (!state) {
      state = { windowStart: nowMs, count: 0 };
      keyStates.set(key, state);
    }
    return state;
  }

  function expireIfNeeded(state: WindowState, nowMs: number): void {
    const elapsed = nowMs - state.windowStart;
    if (elapsed >= WINDOW_SIZE_MS) {
      state.windowStart = nowMs;
      state.count = 0;
    }
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const state = getOrCreateKeyState(key, nowMs);
      expireIfNeeded(state, nowMs);

      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = getOrCreateKeyState(key, nowMs);
      expireIfNeeded(state, nowMs);
      return Math.max(0, MAX_REQUESTS - state.count);
    },

    reset(key: string): void {
      keyStates.delete(key);
    },
  };
}

