export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const entries = new Map<string, { value: unknown; expiresAt: number }>()

  function isExpired(entry: { value: unknown; expiresAt: number }, nowMs: number): boolean {
    return nowMs >= entry.expiresAt
  }

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const effectiveTtl = ttlMs ?? 1000
      const expiresAt = nowMs + effectiveTtl
      entries.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key)
      if (!entry || isExpired(entry, nowMs)) {
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key)
      if (!entry) {
        return false
      }
      if (isExpired(entry, nowMs)) {
        return false
      }
      return true
    },

    delete(key: string): boolean {
      return entries.delete(key)
    },

    size(nowMs: number): number {
      let count = 0
      for (const entry of entries.values()) {
        if (!isExpired(entry, nowMs)) {
          count++
        }
      }
      return count
    },

    clear(): void {
      entries.clear()
    },
  }
}

export function createTtlCache(): TtlCache {
  const store = new Map<string, { value: unknown; expiresAt: number }>()

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const effectiveTtl = ttlMs ?? 1000
      let expiresAt: number
      if (effectiveTtl === 0) {
        expiresAt = nowMs
      } else {
        expiresAt = nowMs + effectiveTtl
      }
      store.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = store.get(key)
      if (!entry) {
        return undefined
      }
      if (nowMs >= entry.expiresAt) {
        store.delete(key)
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = store.get(key)
      if (!entry) {
        return false
      }
      if (nowMs >= entry.expiresAt) {
        store.delete(key)
        return false
      }
      return true
    },

    delete(key: string): boolean {
      return store.delete(key)
    },

    size(nowMs: number): number {
      let count = 0
      const keysToDelete: string[] = []
      for (const [key, entry] of store.entries()) {
        if (nowMs < entry.expiresAt) {
          count++
        } else {
          keysToDelete.push(key)
        }
      }
      for (const key of keysToDelete) {
        store.delete(key)
      }
      return count
    },

    clear(): void {
      store.clear()
    },
  }
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}
